@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@300;400;500&family=Manrope:wght@200;300;400;500;600&display=swap');

:root {
  --ink: #d8fff6;
  --muted: rgba(192, 245, 235, 0.55);
  --faint: rgba(166, 226, 219, 0.22);
  --mint: #74ffe0;
  --mint-soft: #a6ffec;
  --coral: #ff9d72;
  --amber: #ffc786;
  --deep: #03151b;
  --panel: rgba(3, 24, 29, 0.44);
  --line: rgba(146, 255, 232, 0.22);
  --mono: 'DM Mono', 'SFMono-Regular', Consolas, monospace;
  --sans: 'Manrope', 'Helvetica Neue', 'Liberation Sans', sans-serif;
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #01090c;
  color: var(--ink);
  font-family: var(--sans);
  overscroll-behavior: none;
}

button {
  font: inherit;
  color: inherit;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #01090c;
  touch-action: none;
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
}

.hidden {
  display: none !important;
}

.screen-grade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 48% 28%, rgba(80, 255, 221, 0.035), transparent 42%),
    linear-gradient(180deg, rgba(0, 15, 20, 0.05), transparent 35%, rgba(0, 9, 12, 0.3));
  mix-blend-mode: screen;
}

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at 50% 46%, transparent 34%, rgba(0, 8, 11, 0.38) 72%, rgba(0, 4, 6, 0.8) 100%);
}

.grain {
  position: absolute;
  inset: -30%;
  pointer-events: none;
  opacity: 0.08;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.8'/%3E%3C/svg%3E");
  animation: grainShift 0.8s steps(2) infinite;
  mix-blend-mode: soft-light;
}

@keyframes grainShift {
  0% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(2%, -1%, 0); }
  50% { transform: translate3d(-1%, 2%, 0); }
  75% { transform: translate3d(1%, 1%, 0); }
  100% { transform: translate3d(0, 0, 0); }
}

.scanlines {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.11;
  background: repeating-linear-gradient(180deg, transparent 0, transparent 2px, rgba(0, 0, 0, 0.16) 3px, transparent 4px);
  mix-blend-mode: multiply;
}

/* ---------------------------------------------------------------- title */

#title-screen {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: clamp(22px, 3.6vw, 54px);
  background:
    radial-gradient(ellipse at 50% 50%, rgba(1, 16, 20, 0.04) 0%, rgba(1, 12, 15, 0.2) 42%, rgba(0, 7, 9, 0.7) 100%),
    linear-gradient(180deg, rgba(0, 10, 13, 0.38), transparent 32%, transparent 65%, rgba(0, 7, 9, 0.62));
  transition: opacity 0.9s cubic-bezier(0.22, 1, 0.36, 1), filter 0.9s;
