  animation: hudIn 1.1s 0.2s forwards cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes hudIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.hud-top {
  position: absolute;
  top: max(22px, env(safe-area-inset-top));
  left: max(24px, env(safe-area-inset-left));
  right: max(24px, env(safe-area-inset-right));
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 22px;
}

.hud-brand-line {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 400;
  letter-spacing: 0.24em;
  color: rgba(216, 255, 246, 0.92);
}

.hud-brand-line .brand-mark {
  width: 20px;
  height: 20px;
  font-size: 9px;
}

.hud-brand-sub {
  margin-top: 9px;
  margin-left: 30px;
  font-size: 7px;
  letter-spacing: 0.3em;
  color: rgba(176, 234, 224, 0.36);
}

.mission-panel {
  width: 244px;
  padding: 11px 14px 10px;
  border: 1px solid rgba(142, 255, 231, 0.13);
  border-radius: 3px;
  background: linear-gradient(135deg, rgba(4, 30, 34, 0.46), rgba(3, 20, 24, 0.18));
  backdrop-filter: blur(10px);
}

.mission-head {
  display: flex;
  justify-content: space-between;
  font-size: 7px;
  letter-spacing: 0.18em;
  color: rgba(180, 240, 228, 0.45);
}

.mission-head span:last-child {
  color: rgba(122, 255, 230, 0.82);
}

.pips {
  display: flex;
  gap: 5px;
  margin: 9px 0 8px;
}

.pips i {
  flex: 1;
  height: 3px;
  background: rgba(130, 231, 215, 0.13);
  border-radius: 2px;
  transition: background 0.6s, box-shadow 0.6s;
}

.pips i.on {
  background: var(--mint);
  box-shadow: 0 0 10px rgba(116, 255, 224, 0.6);
}

.mission-sub {
  font-size: 7px;
  letter-spacing: 0.17em;
  color: rgba(180, 240, 228, 0.45);
}

.mission-sub b {
  font-weight: 400;
  color: rgba(222, 255, 248, 0.9);
}

.mission-sub span {
  margin: 0 4px;
  color: rgba(116, 255, 224, 0.4);
}

.vitals {
  width: 176px;
  padding-top: 3px;
  text-align: right;
}

.vital-label {
  display: flex;
  justify-content: space-between;
  font-size: 7px;
  letter-spacing: 0.16em;
  color: rgba(180, 240, 228, 0.44);
}

.vital-label b {
  font-weight: 400;
  color: rgba(218, 255, 247, 0.88);
}

.vital-label.minor {
  margin-top: 10px;
  color: rgba(180, 240, 228, 0.3);
}

.vital-label.minor b {
  color: rgba(180, 240, 228, 0.6);
}

.meter {
  height: 3px;
  margin-top: 7px;
  background: rgba(123, 233, 214, 0.1);
  overflow: hidden;
}

.meter div {
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, rgba(87, 255, 219, 0.42), var(--mint));
  box-shadow: 0 0 12px rgba(116, 255, 224, 0.5);
  transition: width 0.25s, background 0.5s;
}

.meter.thin {
  height: 2px;
  margin-top: 5px;
}

.meter.thin div {
  width: 0%;
  background: rgba(255, 199, 134, 0.9);
  box-shadow: 0 0 12px rgba(255, 199, 134, 0.35);
}

.depth-readout {
  position: absolute;
  left: max(26px, env(safe-area-inset-left));
  top: 50%;
  transform: translateY(-52%);
}

.depth-label {
  font-size: 7px;
  letter-spacing: 0.27em;
  color: rgba(180, 240, 228, 0.34);
}

.depth-value {
  display: flex;
  align-items: baseline;
  margin-top: 5px;
  font-family: var(--sans);
  font-weight: 200;
  color: rgba(222, 255, 248, 0.92);
  text-shadow: 0 0 30px rgba(86, 255, 221, 0.12);
}

.depth-value span {
  font-size: 17px;
  margin-right: 2px;
  color: rgba(255, 157, 114, 0.72);
}

.depth-value b {
  font-size: 39px;
  font-weight: 200;
  line-height: 0.9;
  letter-spacing: 0.02em;
  font-variant-numeric: tabular-nums;
}

.depth-value em {
  font-family: var(--mono);
  font-size: 8px;
  font-style: normal;
  letter-spacing: 0.2em;
  margin-left: 7px;
  color: rgba(180, 240, 228, 0.4);
}

.depth-sub {
  margin-top: 8px;
  font-size: 7px;
  letter-spacing: 0.26em;
  color: rgba(255, 199, 134, 0.58);
}

.depth-ruler {
  position: absolute;
  left: 8px;
  top: 25%;
  bottom: 20%;
  width: 12px;
  opacity: 0.72;
}

.ruler-line {
  position: absolute;
  left: 6px;
  top: 0;
  bottom: 0;
  width: 1px;
  background: linear-gradient(180deg, transparent, rgba(143, 239, 223, 0.22) 12%, rgba(143, 239, 223, 0.22) 88%, transparent);
}

.ruler-ticks {
  position: absolute;
  inset: 0;
}

.ruler-ticks span {
  position: absolute;
  top: var(--y);
  left: 0;
  font-size: 5px;
  letter-spacing: 0.12em;
  color: rgba(167, 229, 219, 0.25);
  transform: translateY(-50%);
}

.ruler-ticks span::after {
  content: '';
  position: absolute;
  left: 12px;
  top: 50%;
  width: 3px;
  height: 1px;
  background: rgba(143, 239, 223, 0.25);
}

.ruler-marker {
  position: absolute;
  left: 3px;
  top: 18%;
  width: 7px;
  height: 7px;
  border: 1px solid var(--mint);
  transform: translateY(-50%) rotate(45deg);
  box-shadow: 0 0 10px rgba(116, 255, 224, 0.6);
  transition: top 0.25s;
}

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 30px;
  height: 30px;
  transform: translate(-50%, -50%);
  opacity: 0.5;
}

.crosshair i {
  position: absolute;
  background: rgba(190, 255, 243, 0.75);
}

.crosshair i:first-child {
  left: 50%;
  top: 8px;
  width: 1px;
  height: 5px;
}

.crosshair i:nth-child(2) {
  left: 50%;
  bottom: 8px;
  width: 1px;
  height: 5px;
}

.crosshair span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 3px;
  height: 3px;
  border: 1px solid rgba(190, 255, 243, 0.6);
  border-radius: 50%;
  transform: translate(-50%, -50%);
}

.specimen-card {
  position: absolute;
  right: max(24px, env(safe-area-inset-right));
  top: 50%;
  width: 258px;
  padding: 15px 16px 14px;
  border: 1px solid rgba(141, 255, 230, 0.2);
  border-left: 2px solid rgba(116, 255, 224, 0.72);
  border-radius: 2px;
  background: linear-gradient(135deg, rgba(4, 34, 37, 0.72), rgba(2, 18, 22, 0.38));
  backdrop-filter: blur(14px);
  transform: translateY(-45%);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.45s, transform 0.45s, visibility 0.45s;
  box-shadow: 0 22px 50px rgba(0, 0, 0, 0.18);
}

.specimen-card.visible {
  opacity: 1;
  visibility: visible;
  transform: translateY(-50%);
}

.specimen-top {
  display: flex;
  justify-content: space-between;
  font-size: 6px;
  letter-spacing: 0.22em;
  color: rgba(173, 237, 226, 0.4);
}

.specimen-top span:last-child {
  color: var(--amber);
}

.specimen-card h2 {
  margin: 9px 0 3px;
  font-family: var(--sans);
  font-size: 17px;
  font-weight: 400;
  letter-spacing: 0.13em;
  color: rgba(222, 255, 248, 0.94);
}

.specimen-latin {
  font-size: 7px;
  font-style: italic;
  letter-spacing: 0.16em;
  color: rgba(122, 255, 230, 0.6);
}

.specimen-rule {
  height: 1px;
  margin: 11px 0 10px;
  background: linear-gradient(90deg, rgba(116, 255, 224, 0.3), transparent);
}

.specimen-card p {
  margin: 0;
  font-family: var(--sans);
  font-size: 9.5px;
  font-weight: 300;
  line-height: 1.65;
  letter-spacing: 0.015em;
  color: rgba(194, 241, 233, 0.57);
}

.specimen-stats {
  display: flex;
  gap: 24px;
  margin: 12px 0 13px;
}

.specimen-stats div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.specimen-stats span,
.scan-label span {
  font-size: 6px;
  letter-spacing: 0.18em;
  color: rgba(173, 237, 226, 0.34);
}

.specimen-stats b {
  font-size: 8px;
  font-weight: 400;
  letter-spacing: 0.12em;
  color: rgba(213, 255, 247, 0.74);
}

.scan-label {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.scan-label b {
  font-size: 8px;
  font-weight: 400;
  color: rgba(122, 255, 230, 0.82);
}

.scan-track {
  height: 2px;
  margin: 7px 0 9px;
  background: rgba(120, 230, 212, 0.12);
}

.scan-track div {
  width: 0%;
  height: 100%;
  background: var(--mint);
  box-shadow: 0 0 10px rgba(116, 255, 224, 0.5);
  transition: width 0.15s linear;
}

.scan-hint {
  font-size: 6px;
  letter-spacing: 0.18em;
  color: rgba(173, 237, 226, 0.4);
}

kbd {
  display: inline-grid;
  place-items: center;
  min-width: 14px;
  height: 14px;
  padding: 0 3px;
  border: 1px solid rgba(167, 237, 225, 0.24);
  border-radius: 2px;
  font-family: var(--mono);
  font-size: 7px;
  font-weight: 400;
  color: rgba(205, 255, 246, 0.7);
}

.scan-prompt {
  position: absolute;
  left: 50%;
  bottom: 84px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 9px 14px 9px 11px;
  border: 1px solid rgba(129, 255, 228, 0.18);
  border-radius: 100px;
  background: rgba(3, 25, 29, 0.52);
  backdrop-filter: blur(10px);
  transform: translateX(-50%);
  transition: opacity 0.3s;
}

.prompt-pulse {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--mint);
  box-shadow: 0 0 0 0 rgba(116, 255, 224, 0.6);
  animation: promptPulse 1.8s infinite;
}

@keyframes promptPulse {
  0% { box-shadow: 0 0 0 0 rgba(116, 255, 224, 0.5); }
  70% { box-shadow: 0 0 0 7px rgba(116, 255, 224, 0); }
  100% { box-shadow: 0 0 0 0 rgba(116, 255, 224, 0); }
}

.scan-prompt div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.scan-prompt b {
  font-size: 8px;
  font-weight: 400;
  letter-spacing: 0.2em;
  color: rgba(219, 255, 247, 0.86);
}

.scan-prompt small {
  font-size: 6px;
  letter-spacing: 0.17em;
  color: rgba(173, 237, 226, 0.42);
}

.radar-wrap {
  position: absolute;
  right: max(28px, env(safe-area-inset-right));
  bottom: max(24px, env(safe-area-inset-bottom));
  width: 124px;
  height: 146px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

#radar {
  width: 124px;
  height: 124px;
  opacity: 0.8;
}

.radar-label {
  display: flex;
  justify-content: space-between;
  width: 124px;
  margin-top: 1px;
  font-size: 6px;
  letter-spacing: 0.18em;
  color: rgba(173, 237, 226, 0.33);
}

.radar-label b {
  font-weight: 400;
  color: rgba(122, 255, 230, 0.55);
}

.controls-hint {
  position: absolute;
  left: 50%;
  bottom: max(24px, env(safe-area-inset-bottom));
  display: flex;
  gap: 17px;
  transform: translateX(-50%);
  font-size: 6px;
  letter-spacing: 0.14em;
  color: rgba(173, 237, 226, 0.38);
  white-space: nowrap;
  transition: opacity 1.2s;
}

.controls-hint span {
  display: flex;
  align-items: center;
  gap: 5px;
}

.controls-hint kbd {
  min-width: 12px;
  height: 12px;
  font-size: 6px;
  border-color: rgba(167, 237, 225, 0.16);
  color: rgba(205, 255, 246, 0.5);
}

.status-toast {
  position: absolute;
  left: 50%;
  top: 18%;
  padding: 8px 17px;
  border: 1px solid rgba(128, 255, 228, 0.22);
  border-radius: 100px;
  background: rgba(3, 26, 30, 0.62);
  backdrop-filter: blur(10px);
  font-size: 7px;
  letter-spacing: 0.22em;
  color: rgba(218, 255, 247, 0.86);
  opacity: 0;
  transform: translate(-50%, -8px);
  transition: opacity 0.35s, transform 0.35s;
  white-space: nowrap;
}

.status-toast.visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

.damage-flash,
.pulse-flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
}

.damage-flash {
  background: radial-gradient(ellipse at center, transparent 25%, rgba(255, 72, 50, 0.28) 75%, rgba(255, 44, 24, 0.5) 100%);
  mix-blend-mode: screen;
}

.damage-flash.hit {
  animation: damageFlash 0.7s ease-out;
}

@keyframes damageFlash {
  0% { opacity: 0; }
  12% { opacity: 1; }
  100% { opacity: 0; }
}

.pulse-flash {
  background: radial-gradient(ellipse at center, rgba(130, 255, 232, 0.2), transparent 62%);
  mix-blend-mode: screen;
}

.pulse-flash.fire {
  animation: pulseFlash 1.1s ease-out;
}

@keyframes pulseFlash {
  0% { opacity: 0; }
  8% { opacity: 1; }
  100% { opacity: 0; }
}

.sound-btn {
  position: absolute;
  left: max(27px, env(safe-area-inset-left));
  bottom: max(26px, env(safe-area-inset-bottom));
  width: 28px;
  height: 28px;
  border: 1px solid rgba(145, 245, 227, 0.16);
  border-radius: 50%;
  background: rgba(3, 24, 28, 0.32);
  cursor: pointer;
  pointer-events: auto;
  display: grid;
  place-items: center;
  opacity: 0.55;
  transition: opacity 0.3s, border-color 0.3s;
}

.sound-btn:hover {
  opacity: 1;
  border-color: rgba(145, 245, 227, 0.4);
}

.sound-btn span {
  width: 7px;
  height: 7px;
  border: 1px solid var(--mint);
  border-radius: 50%;
}

.sound-btn i {
  position: absolute;
  width: 1px;
  height: 11px;
  background: var(--coral);
  transform: rotate(-45deg);
  opacity: 0;
}

.sound-btn.muted i {
  opacity: 1;
}

/* ---------------------------------------------------------------- touch */

.mobile-controls {
  display: none;
}

.look-zone {
  position: absolute;
  right: 0;
  top: 15%;
  bottom: 0;
  width: 48%;
  pointer-events: auto;
}

.look-zone span {
  position: absolute;
  right: 18px;
  top: 23%;
  font-size: 6px;
  letter-spacing: 0.2em;
  color: rgba(173, 237, 226, 0.22);
}

.stick-zone {
  position: absolute;
  left: max(20px, env(safe-area-inset-left));
  bottom: max(30px, env(safe-area-inset-bottom));
  width: 116px;
  height: 116px;
  pointer-events: auto;
}

.stick-zone > span {
  position: absolute;
  left: 50%;
  bottom: -13px;
  transform: translateX(-50%);
  font-size: 6px;
  letter-spacing: 0.2em;
  color: rgba(173, 237, 226, 0.28);
}

.stick-ring {
  width: 100%;
  height: 100%;
  border: 1px solid rgba(142, 255, 231, 0.19);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(40, 170, 151, 0.08), transparent 65%);
  box-shadow: inset 0 0 30px rgba(60, 255, 221, 0.04);
}

.stick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 44px;
  height: 44px;
  margin: -22px 0 0 -22px;
  border: 1px solid rgba(151, 255, 234, 0.4);
  border-radius: 50%;
  background: rgba(7, 48, 50, 0.48);
  box-shadow: 0 0 24px rgba(74, 255, 220, 0.08);
  transition: transform 0.08s;
}

.touch-actions {
  position: absolute;
  right: max(18px, env(safe-area-inset-right));
  bottom: max(28px, env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: repeat(2, 50px);
  gap: 8px;
  pointer-events: auto;
}

.touch-actions button {
  height: 44px;
  border: 1px solid rgba(141, 255, 230, 0.23);
  border-radius: 50%;
  background: rgba(3, 28, 31, 0.46);
  backdrop-filter: blur(8px);
  font-family: var(--mono);
  font-size: 6px;
  letter-spacing: 0.12em;
  color: rgba(216, 255, 247, 0.72);
}

.touch-actions button:active {
  background: rgba(52, 213, 184, 0.2);
  border-color: rgba(141, 255, 230, 0.6);
}

.touch-actions .touch-scan {
  grid-column: 1 / 3;
  height: 38px;
  border-radius: 100px;
  color: var(--mint);
  font-size: 7px;
  letter-spacing: 0.24em;
}

.touch-actions .touch-pulse {
  grid-column: 1 / 3;
  height: 38px;
  border-radius: 100px;
  color: var(--amber);
  font-size: 7px;
  letter-spacing: 0.24em;
}

@media (pointer: coarse), (max-width: 820px) {
  .mobile-controls {
    display: block;
    position: absolute;
    inset: 0;
    pointer-events: none;
  }

  .controls-hint,
  .depth-ruler,
  .sound-btn {
    display: none;
  }

  .radar-wrap {
    width: 92px;
    height: 108px;
    right: max(16px, env(safe-area-inset-right));
    bottom: auto;
    top: 118px;
  }

  #radar {
    width: 92px;
    height: 92px;
  }

  .radar-label {
    width: 92px;
    font-size: 5px;
  }

  .mission-panel {
    position: absolute;
    top: 48px;
    left: 0;
    width: 200px;
    padding: 8px 10px;
  }

  .hud-top {
    top: max(16px, env(safe-area-inset-top));
    left: max(18px, env(safe-area-inset-left));
    right: max(18px, env(safe-area-inset-right));
    display: block;
  }

  .vitals {
    position: absolute;
    right: 0;
    top: 0;
    width: 124px;
  }

  .depth-readout {
    top: 132px;
    left: max(18px, env(safe-area-inset-left));
    transform: none;
  }

  .depth-value b {
    font-size: 29px;
  }

  .depth-value span {
    font-size: 14px;
  }

  .specimen-card {
    right: 14px;
    top: 188px;
    width: 216px;
    padding: 11px 12px;
    transform: none;
    max-height: 42vh;
    overflow: hidden;
  }

  .specimen-card.visible {
    transform: none;
  }

  .specimen-card p {
    display: none;
  }

  .specimen-stats {
    margin: 8px 0 9px;
  }

  .specimen-card h2 {
    font-size: 14px;
  }

  .scan-prompt {
    bottom: 192px;
    max-width: calc(100vw - 28px);
  }

  .status-toast {
    top: 12%;
    max-width: 80vw;
    text-align: center;
  }

  .crosshair {
    opacity: 0.38;
  }

  .title-top,
  .title-bottom {
    font-size: 7px;
  }

  .title-bottom {
    display: block;
    text-align: center;
  }

  .title-specs {
    justify-content: center;
    gap: 22px;
  }

  .title-bottom p {
    margin-top: 12px;
    text-align: center;
    font-size: 6px;
  }

  .title-center {
    transform: translateY(-2vh);
  }

  h1 {
    font-size: clamp(58px, 18vw, 100px);
    letter-spacing: 0.06em;
    text-indent: 0.06em;
  }

  .kicker {
    font-size: 7px;
    letter-spacing: 0.25em;
    line-height: 1.8;
  }

  .lede {
    font-size: 11px;
    line-height: 1.75;
    padding: 0 14px;
  }

  .start-wrap {
    margin-top: 30px;
  }

  #start-btn {
    width: 148px;
    height: 48px;
  }

  .hud-brand-sub {
    display: none;
  }

  .hud-brand-line {
    font-size: 11px;
  }
}

/* ---------------------------------------------------------------- end */

.end-screen {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: center;
  background:
    radial-gradient(ellipse at 50% 45%, rgba(6, 40, 43, 0.6), rgba(1, 8, 11, 0.94) 72%),
    rgba(1, 8, 11, 0.86);
  backdrop-filter: blur(12px);
  animation: endIn 1.2s cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes endIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

.end-inner {
  width: min(88vw, 580px);
  text-align: center;
}

.end-kicker {
  margin: 0 0 18px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.4em;
  color: rgba(255, 199, 134, 0.6);
}

.end-inner h2 {
  margin: 0;
  font-family: var(--sans);
  font-size: clamp(34px, 6vw, 76px);
  font-weight: 200;
  line-height: 1;
  letter-spacing: 0.08em;
  color: rgba(222, 255, 248, 0.94);
  text-shadow: 0 0 50px rgba(88, 255, 220, 0.1);
}

.end-inner > p:not(.end-kicker) {
  max-width: 440px;
  margin: 22px auto 0;
  font-family: var(--sans);
  font-size: 13px;
  font-weight: 300;
  line-height: 1.8;
  color: rgba(196, 241, 233, 0.55);
}

.end-stats {
  display: flex;
  justify-content: center;
  gap: clamp(24px, 6vw, 72px);
  margin: 38px 0;
  padding: 20px 0;
  border-top: 1px solid rgba(145, 245, 227, 0.12);
  border-bottom: 1px solid rgba(145, 245, 227, 0.12);
}

.end-stats div {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-family: var(--mono);
}

.end-stats span {
  font-size: 6px;
  letter-spacing: 0.2em;
  color: rgba(173, 237, 226, 0.34);
}

.end-stats b {
  font-family: var(--sans);
  font-size: 22px;
  font-weight: 200;
  letter-spacing: 0.08em;
  color: rgba(222, 255, 248, 0.9);
}

#restart-btn {
  height: 48px;
  padding: 0 36px;
  border: 1px solid rgba(122, 255, 230, 0.48);
  border-radius: 100px;
  background: rgba(5, 36, 39, 0.34);
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.3s, border-color 0.3s;
}

#restart-btn:hover {
  background: rgba(36, 143, 125, 0.18);
  border-color: rgba(122, 255, 230, 0.9);
}

/* ---------------------------------------------------------------- loading */

.loading {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 20px;
  background: #01090c;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.34em;
  color: rgba(173, 237, 226, 0.45);
  transition: opacity 0.9s, visibility 0.9s;
}

.loading.done {
  opacity: 0;
  visibility: hidden;
}

.loading-ring {
  width: 38px;
  height: 38px;
  border: 1px solid rgba(116, 255, 224, 0.12);
  border-top-color: rgba(116, 255, 224, 0.7);
  border-radius: 50%;
  animation: spin 1.1s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@media (max-width: 480px) {
  .mission-panel {
    width: 178px;
  }

  .vitals {
    width: 106px;
  }

  .vital-label {
    font-size: 6px;
  }

  .specimen-card {
    width: 196px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .grain,
  .live-dot,
  .prompt-pulse,
  .loading-ring {
    animation: none;
  }
}

import * as THREE from 'three';

export const TAU = Math.PI * 2;

export function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

export function lerp(a, b, t) {
  return a + (b - a) * t;
}

export function smoothstep(edge0, edge1, x) {
  const t = clamp((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

export function damp(current, target, lambda, dt) {
  return lerp(current, target, 1 - Math.exp(-lambda * dt));
}

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function range(rng, min, max) {
  return min + rng() * (max - min);
}

export function pick(rng, list) {
  return list[Math.floor(rng() * list.length) % list.length];
}

function hash2(x, y) {
  const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453123;
  return s - Math.floor(s);
}

function valueNoise(x, y) {
  const ix = Math.floor(x);
  const iy = Math.floor(y);
  const fx = x - ix;
  const fy = y - iy;
  const ux = fx * fx * (3 - 2 * fx);
  const uy = fy * fy * (3 - 2 * fy);
  const a = hash2(ix, iy);
  const b = hash2(ix + 1, iy);
  const c = hash2(ix, iy + 1);
  const d = hash2(ix + 1, iy + 1);
  return lerp(lerp(a, b, ux), lerp(c, d, ux), uy);
}

export function fbm(x, y, octaves = 4) {
  let value = 0;
  let amplitude = 0.5;
  let frequency = 1;
  for (let i = 0; i < octaves; i += 1) {
    value += valueNoise(x * frequency, y * frequency) * amplitude;
    frequency *= 2.03;
    amplitude *= 0.5;
  }
  return value;
}

export function terrainHeight(x, z) {
  const r = Math.hypot(x, z);
  let height = -116;
  height += fbm(x * 0.0075 + 11.3, z * 0.0075 - 4.2, 4) * 34;
  height += fbm(x * 0.032 - 7.8, z * 0.032 + 2.9, 3) * 8;
  height += Math.max(0, 1 - r / 130) * 7;
  const trench = Math.exp(-(((x + 82) ** 2) / 4600 + ((z - 32) ** 2) / 5200));
  height -= trench * 26;
  const basin = Math.exp(-((x * x + z * z) / 18000));
  height -= basin * 8;
  return height;
}

export function makeGlowTexture(size = 128) {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  const gradient = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  gradient.addColorStop(0, 'rgba(255,255,255,1)');
  gradient.addColorStop(0.16, 'rgba(255,255,255,0.95)');
  gradient.addColorStop(0.38, 'rgba(255,255,255,0.38)');
  gradient.addColorStop(0.7, 'rgba(255,255,255,0.08)');
  gradient.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, size, size);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.needsUpdate = true;
  return texture;
}

export function makeSoftTexture(size = 64) {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  const gradient = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  gradient.addColorStop(0, 'rgba(255,255,255,0.95)');
  gradient.addColorStop(0.45, 'rgba(255,255,255,0.22)');
  gradient.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, size, size);
  return new THREE.CanvasTexture(canvas);
}

export function makeLineMaterial(color, opacity = 0.6) {
  return new THREE.LineBasicMaterial({
    color,
    transparent: true,
    opacity,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
}

export function createGlowSprite(texture, color, scale = 2, opacity = 0.8) {
  const material = new THREE.SpriteMaterial({
    map: texture,
    color,
    transparent: true,
    opacity,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    toneMapped: false,
  });
  const sprite = new THREE.Sprite(material);
  sprite.scale.setScalar(scale);
  return sprite;
}

export function createPointsMaterial(texture, color, size = 2, opacity = 0.7) {
  return new THREE.PointsMaterial({
    map: texture,
    color,
    size,
    sizeAttenuation: true,
    transparent: true,
    opacity,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    toneMapped: false,
  });
}

export function setShadowed(object, cast = false, receive = false) {
  object.traverse((child) => {
    if (child.isMesh) {
      child.castShadow = cast;
      child.receiveShadow = receive;
    }
  });
}

export function makeCurve(points, closed = false) {
  return new THREE.CatmullRomCurve3(points, closed, 'catmullrom', 0.35);
}

export function disposeObject(object) {
  object.traverse((child) => {
    if (child.geometry) child.geometry.dispose();
    if (child.material) {
      if (Array.isArray(child.material)) child.material.forEach((m) => m.dispose());
      else child.material.dispose();
    }
  });
}

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.started = false;
    this.droneNodes = [];
    this.lastCall = 0;
    this.ambientTimer = null;
  }

  start() {
    if (this.started) {
      if (this.ctx?.state === 'suspended') this.ctx.resume();
      return;
    }
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) return;
    this.ctx = new AudioContext();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.55;
    this.master.connect(this.ctx.destination);
    this.started = true;
    this.buildAmbience();
    this.scheduleCall();
  }

  buildAmbience() {
    const ctx = this.ctx;
    const now = ctx.currentTime;

    const low = ctx.createGain();
    low.gain.value = 0.038;
    low.connect(this.master);

    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 180;
    filter.Q.value = 1.4;
    filter.connect(low);

    [43.65, 55, 65.41].forEach((frequency, index) => {
      const osc = ctx.createOscillator();
      osc.type = index === 2 ? 'sine' : 'triangle';
      osc.frequency.value = frequency;
      osc.detune.value = index === 1 ? 7 : -5;
      const gain = ctx.createGain();
      gain.gain.value = index === 2 ? 0.22 : 0.4;
      osc.connect(gain);
      gain.connect(filter);
      osc.start(now);
      this.droneNodes.push(osc);
    });

    const lfo = ctx.createOscillator();
    const lfoGain = ctx.createGain();
    lfo.frequency.value = 0.055;
    lfoGain.gain.value = 70;
    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);
    lfo.start(now);
    this.droneNodes.push(lfo);

    // Filtered noise: distant current / pressure.
    const length = ctx.sampleRate * 6;
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i += 1) {
      const white = Math.random() * 2 - 1;
      last = last * 0.985 + white * 0.015;
      data[i] = last;
    }
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    noise.loop = true;
    const noiseFilter = ctx.createBiquadFilter();
    noiseFilter.type = 'bandpass';
    noiseFilter.frequency.value = 320;
    noiseFilter.Q.value = 0.45;
    const noiseGain = ctx.createGain();
    noiseGain.gain.value = 0.028;
    noise.connect(noiseFilter);
    noiseFilter.connect(noiseGain);
    noiseGain.connect(this.master);
    noise.start(now);
    this.noise = noise;

    const currentLfo = ctx.createOscillator();
    const currentGain = ctx.createGain();
    currentLfo.frequency.value = 0.085;
    currentGain.gain.value = 0.014;
    currentLfo.connect(currentGain);
    currentGain.connect(noiseGain.gain);
    currentLfo.start(now);
    this.droneNodes.push(currentLfo);
  }

  scheduleCall() {
    if (!this.started) return;
    const delay = 14000 + Math.random() * 22000;
    this.ambientTimer = window.setTimeout(() => {
      this.creatureCall();
      this.scheduleCall();
    }, delay);
  }

  creatureCall() {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const filter = ctx.createBiquadFilter();
    osc.type = 'sine';
    const base = 92 + Math.random() * 80;
    osc.frequency.setValueAtTime(base, now);
    osc.frequency.exponentialRampToValueAtTime(base * 1.55, now + 1.2);
    osc.frequency.exponentialRampToValueAtTime(base * 0.62, now + 5.5);
    filter.type = 'lowpass';
    filter.frequency.value = 520;
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.035, now + 1.4);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 6);
    osc.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    osc.start(now);
    osc.stop(now + 6.2);
  }

  tone(frequency, duration, volume = 0.05, type = 'sine', slide = 1) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(frequency, now);
    if (slide !== 1) osc.frequency.exponentialRampToValueAtTime(frequency * slide, now + duration);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(volume, now + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(now);
    osc.stop(now + duration + 0.03);
  }

  ping() {
    this.tone(1280, 1.7, 0.06, 'sine', 0.36);
    window.setTimeout(() => this.tone(860, 2.2, 0.022, 'sine', 0.5), 120);
  }

  scanTick() {
    this.tone(640, 0.08, 0.018, 'square');
  }

  discovered() {
    this.tone(392, 0.5, 0.04, 'sine');
    window.setTimeout(() => this.tone(587.33, 0.7, 0.032, 'sine'), 130);
    window.setTimeout(() => this.tone(783.99, 1.1, 0.025, 'sine'), 280);
  }

  collect() {
    this.tone(1046.5, 0.25, 0.028, 'sine', 1.45);
    window.setTimeout(() => this.tone(1568, 0.4, 0.018, 'sine', 1.1), 80);
  }

  hurt() {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(110, now);
    osc.frequency.exponentialRampToValueAtTime(36, now + 0.7);
    gain.gain.setValueAtTime(0.07, now);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.8);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(now);
    osc.stop(now + 0.82);
  }

  toggle() {
    this.muted = !this.muted;
    if (this.master) {
      const target = this.muted ? 0 : 0.55;
      this.master.gain.setTargetAtTime(target, this.ctx.currentTime, 0.08);
    }
    return this.muted;
  }

  suspend() {
    if (this.ctx?.state === 'running') this.ctx.suspend();
  }
}

