import * as THREE from 'three';
import {
  TAU,
  clamp,
  damp,
  lerp,
  mulberry32,
  range,
  makeCurve,
  createGlowSprite,
  createPointsMaterial,
} from './utils.js';

export const SPECIES = {
  veil: {
    name: 'VEIL SOVEREIGN',
    latin: 'Velifera cathedralis',
    size: '28 M',
    behavior: 'DRIFT / FILTER',
    range: 48,
    color: 0x8dffe3,
    index: 1,
    desc: 'A cathedral-sized filter feeder that drifts on the deep current, singing through the crown of its six translucent sails.',
  },
  rift: {
    name: 'RIFT HUNTER',
    latin: 'Falx abyssi',
    size: '22 M',
    behavior: 'STALK / AMBUSH',
    range: 42,
    color: 0xffa477,
    index: 2,
    desc: 'An apex pursuit predator. It circles before it commits, reading movement through six pressure-sensitive eyes.',
  },
  spire: {
    name: 'SPIRE DRIFTER',
    latin: 'Spiralis aurora',
    size: '4.8 M',
    behavior: 'GRAZE / FLEE',
    range: 18,
    color: 0xffc98f,
    index: 3,
    desc: 'A coiled grazer that farms light with feather arms. When threatened it folds into its spiral and sinks.',
  },
  shoal: {
    name: 'GLASS SHOAL',
    latin: 'Vitreus grex',
    size: '0.6 M',
    behavior: 'SCHOOL / SCATTER',
    range: 20,
    color: 0x8ff9ff,
    index: 4,
    desc: 'A school of transparent shard-fish. Each body is a living lens; together they behave as one nervous animal.',
  },
  bell: {
    name: 'BELL BLOOM',
    latin: 'Campana lucens',
    size: '0.9 M',
    behavior: 'PULSE / DRIFT',
    range: 17,
    color: 0xb0a3ff,
    index: 5,
    desc: 'A drifting colony of bell-shaped organisms that pulse in unison, broadcasting soft light into the water column.',
  },
};

const BODY_VERTEX = `
#include <common>
uniform float uTime;
uniform float uPhase;
varying float vWave;
`;

const BODY_WAVE = `
#include <begin_vertex>
float bodyWave = sin(position.z * 0.32 + uTime * 1.05 + uPhase) * 0.06;
transformed.y += bodyWave;
vWave = bodyWave;
`;

const BODY_FRAGMENT = `
#include <common>
uniform float uTime;
varying float vWave;
`;

const BODY_FRAGMENT_PATCH = `
#include <emissivemap_fragment>
float pulse = 0.5 + 0.5 * sin(uTime * 0.8 + vWave * 24.0);
totalEmissiveRadiance += vec3(0.01, 0.085, 0.075) * pulse;
`;

function bodyMaterial(color = 0x0a252d, seed = 1) {
  const material = new THREE.MeshPhysicalMaterial({
    color,
    vertexColors: true,
    roughness: 0.38,
    metalness: 0.42,
    clearcoat: 0.72,
    clearcoatRoughness: 0.24,
    sheen: 0.5,
    sheenColor: new THREE.Color(0x3bffe0),
    sheenRoughness: 0.62,
    emissive: new THREE.Color(0x021c20),
    emissiveIntensity: 0.7,
    iridescence: 0.65,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [100, 420],
  });
  material.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = { value: 0 };
    shader.uniforms.uPhase = { value: seed * 2.7 };
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', BODY_VERTEX)
      .replace('#include <begin_vertex>', BODY_WAVE);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', BODY_FRAGMENT)
      .replace('#include <emissivemap_fragment>', BODY_FRAGMENT_PATCH);
    material.userData.shader = shader;
  };
  return material;
}

function finMaterial(color, glow, opacity = 0.58, phase = 0) {
  return new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uPhase: { value: phase },
      uColor: { value: new THREE.Color(color) },
      uGlow: { value: new THREE.Color(glow) },
      uOpacity: { value: opacity },
    },
    vertexShader: `
      uniform float uTime;
      uniform float uPhase;
      varying vec2 vUv;
      varying vec3 vWorld;
      varying vec3 vNormalW;
      void main() {
        vec3 p = position;
        float span = abs(p.x);
        float wave = sin(p.x * 0.34 + p.z * 0.24 + uTime * 0.92 + uPhase) * 0.16 * (0.22 + span * 0.075);
        p.y += wave;
        p.z += cos(p.x * 0.2 + uTime * 0.58 + uPhase) * 0.1 * (0.15 + span * 0.035);
        vec4 wp = modelMatrix * vec4(p, 1.0);
        vWorld = wp.xyz;
        vNormalW = normalize(mat3(modelMatrix) * normal);
        vUv = uv;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: `
      uniform float uTime;
      uniform vec3 uColor;
      uniform vec3 uGlow;
      uniform float uOpacity;
      varying vec2 vUv;
      varying vec3 vWorld;
      varying vec3 vNormalW;
      void main() {
        vec3 N = normalize(vNormalW);
        vec3 V = normalize(cameraPosition - vWorld);
        float fres = pow(1.0 - abs(dot(N, V)), 2.0);
        float edge = smoothstep(0.43, 0.5, abs(vUv.y - 0.5));
        float tip = smoothstep(0.86, 1.0, vUv.x);
        float veins = pow(abs(sin(vUv.x * 31.0 + sin(vUv.y * 11.0 + uTime * 0.13) * 1.4)), 14.0);
        vec3 col = uColor * (0.23 + 0.72 * fres) + uGlow * (edge * 1.45 + tip * 1.8 + veins * 0.7);
        float alpha = uOpacity * (0.3 + 0.7 * fres) + edge * 0.28 + tip * 0.22;
        gl_FragColor = vec4(col, alpha);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: false,
    blending: THREE.NormalBlending,
  });
}

function tentacleMaterial(color, glow, opacity = 0.5, phase = 0) {
  const material = new THREE.MeshStandardMaterial({
    color,
    emissive: glow,
    emissiveIntensity: 0.8,
    roughness: 0.45,
    metalness: 0.15,
    transparent: true,
    opacity,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  material.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = { value: 0 };
    shader.uniforms.uPhase = { value: phase };
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nuniform float uTime;\nuniform float uPhase;')
      .replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
        float sway = sin(position.z * 0.38 + uTime * 1.3 + uPhase) * 0.15 * (0.25 + abs(position.z) * 0.035);
        transformed.x += sway;
        transformed.y += cos(position.z * 0.22 + uTime * 0.85 + uPhase) * 0.1;`
      );
    material.userData.shader = shader;
  };
  return material;
}

function createLoftGeometry({ length = 16, segments = 36, radial = 18, profile, seed = 1, ridge = 0.055 }) {
  const positions = [];
  const uvs = [];
  const colors = [];
  const indices = [];
  const rng = mulberry32(seed);
  const twist = range(rng, -0.1, 0.1);

  for (let i = 0; i <= segments; i += 1) {
    const t = i / segments;
    const z = -length / 2 + t * length;
    const [rx, ry] = profile(t);
    for (let j = 0; j <= radial; j += 1) {
      const angle = (j / radial) * TAU;
      const ripple = 1 + Math.sin(angle * 7 + t * 12 + seed) * ridge + Math.sin(angle * 3 - t * 8) * ridge * 0.48;
      const x = Math.cos(angle) * rx * ripple;
      const y = Math.sin(angle) * ry * ripple;
      positions.push(x, y, z);
      uvs.push(j / radial, t);
      const topness = clamp(y / Math.max(ry, 0.001), -1, 1);
      const shade = 0.4 + topness * 0.19 + Math.sin(t * 19 + seed) * 0.035 + twist;
      colors.push(shade * 0.57, shade * 0.93, shade * 0.88);
    }
  }

  for (let i = 0; i < segments; i += 1) {
    for (let j = 0; j < radial; j += 1) {
      const a = i * (radial + 1) + j;
      const b = a + radial + 1;
      const c = b + 1;
      const d = a + 1;
      indices.push(a, b, d, b, c, d);
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

function createFinGeometry({
  span = 10,
  chord = 5,
  sweep = 1.2,
  lift = 1.1,
  droop = 0.7,
  segments = 30,
  chordSegments = 8,
  scallop = 0,
}) {
  const positions = [];
  const uvs = [];
  const indices = [];

  for (let i = 0; i <= segments; i += 1) {
    const u = i / segments;
    const x = span * u;
    const widthBase = chord * (0.3 + 0.7 * Math.pow(Math.sin(Math.PI * Math.min(1, u * 1.04)), 0.72)) * (1 - u * 0.22);
    const width = widthBase * (1 + Math.sin(u * Math.PI * 7) * scallop);
    const y = Math.sin(u * Math.PI * 0.52) * lift - u * u * droop;
    const centerZ = -sweep * u * u;
    for (let j = 0; j <= chordSegments; j += 1) {
      const v = (j / chordSegments) * 2 - 1;
      const z = centerZ + v * width * 0.5;
      const y2 = y - v * v * width * 0.1;
      positions.push(x, y2, z);
      uvs.push(u, j / chordSegments);
    }
  }

  for (let i = 0; i < segments; i += 1) {
    for (let j = 0; j < chordSegments; j += 1) {
      const a = i * (chordSegments + 1) + j;
      const b = a + chordSegments + 1;
      const c = b + 1;
      const d = a + 1;
      indices.push(a, b, d, b, c, d);
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

function createPetalGeometry(length = 2.4, width = 2.1) {
  const segments = 12;
  const across = 7;
  const positions = [];
  const uvs = [];
  const indices = [];
  for (let i = 0; i <= segments; i += 1) {
    const u = i / segments;
    const z = u * length;
    const w = Math.pow(Math.sin(Math.PI * u), 0.7) * width;
    for (let j = 0; j <= across; j += 1) {
      const v = (j / across) * 2 - 1;
      positions.push(v * w * 0.5, Math.sin(u * Math.PI) * 0.45 + v * v * 0.22, z);
      uvs.push(u, j / across);
    }
  }
  for (let i = 0; i < segments; i += 1) {
    for (let j = 0; j < across; j += 1) {
      const a = i * (across + 1) + j;
      const b = a + across + 1;
      const c = b + 1;
      const d = a + 1;
      indices.push(a, b, d, b, c, d);
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

function createGlowPoints(points, color, size, texture, opacity = 0.9) {
  const geometry = new THREE.BufferGeometry().setFromPoints(points);
  const material = createPointsMaterial(texture, color, size, opacity);
  const cloud = new THREE.Points(geometry, material);
  cloud.frustumCulled = false;
  return cloud;
}

function attachGlow(root, texture, color, scale, position, opacity = 0.8) {
  const glow = createGlowSprite(texture, color, scale, opacity);
  glow.position.copy(position);
  root.add(glow);
  return glow;
}

function buildVeil(timeUniform, glowTexture, seed = 3) {
  const root = new THREE.Group();
  const bank = new THREE.Group();
  root.add(bank);

  const bodyMat = bodyMaterial(0x09262e, seed);
  bodyMat.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = timeUniform;
    shader.uniforms.uPhase = { value: 1.2 };
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', BODY_VERTEX)
      .replace('#include <begin_vertex>', BODY_WAVE);
    shader.fragmentShader = shader.fragmentShader
      .replace('#include <common>', BODY_FRAGMENT)
      .replace('#include <emissivemap_fragment>', BODY_FRAGMENT_PATCH);
    bodyMat.userData.shader = shader;
  };

  const bodyGeometry = createLoftGeometry({
    length: 17,
    segments: 44,
    radial: 22,
    seed,
    ridge: 0.07,
    profile: (t) => {
      const bell = Math.pow(Math.sin(Math.PI * t), 0.62);
      return [0.32 + bell * 2.55, 0.38 + bell * 2.9];
    },
  });
  const body = new THREE.Mesh(bodyGeometry, bodyMat);
  body.rotation.z = 0.04;
  bank.add(body);

  const crown = new THREE.Group();
  crown.position.z = 1.8;
  bank.add(crown);

  const sailData = [
    { angle: Math.PI / 2, span: 11.5, chord: 7.5, sweep: 2.6, lift: 1.8, droop: 2.2, color: 0x0c3a3d, glow: 0x5dffd9, opacity: 0.58 },
    { angle: Math.PI * 0.17, span: 10.4, chord: 6.4, sweep: 2.2, lift: 1.4, droop: 2.8, color: 0x0b3439, glow: 0x69ffe1, opacity: 0.52 },
    { angle: Math.PI * 0.83, span: 10.8, chord: 6.8, sweep: 2.4, lift: 1.5, droop: 2.5, color: 0x0b3439, glow: 0x69ffe1, opacity: 0.52 },
    { angle: -Math.PI / 2, span: 8.2, chord: 5.2, sweep: 2.1, lift: 1.0, droop: 2.2, color: 0x0a2e34, glow: 0x42e7cb, opacity: 0.44 },
    { angle: Math.PI * 0.5 + 0.38, span: 7.1, chord: 4.6, sweep: 2.6, lift: 1.2, droop: 2.1, color: 0x0b3035, glow: 0x48efd2, opacity: 0.42 },
  ];

  sailData.forEach((sail, index) => {
    const material = finMaterial(sail.color, sail.glow, sail.opacity, index * 1.7);
    material.uniforms.uTime = timeUniform;
    const geometry = createFinGeometry({
      span: sail.span,
      chord: sail.chord,
      sweep: sail.sweep,
      lift: sail.lift,
      droop: sail.droop,
      segments: 34,
      chordSegments: 10,
      scallop: 0.09,
    });
    const fin = new THREE.Mesh(geometry, material);
    fin.rotation.z = sail.angle;
    fin.rotation.y = -0.08 + index * 0.025;
    fin.position.set(Math.cos(sail.angle) * 1.5, Math.sin(sail.angle) * 1.7, 0);
    crown.add(fin);
  });

  const haloGeometry = new THREE.TorusGeometry(3.25, 0.055, 5, 84);
  const haloMat = new THREE.MeshBasicMaterial({ color: 0x83ffe5, transparent: true, opacity: 0.62, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
  const halo = new THREE.Mesh(haloGeometry, haloMat);
  halo.position.z = 6.2;
  halo.rotation.x = 0.05;
  bank.add(halo);

  const halo2 = halo.clone();
  halo2.scale.setScalar(1.16);
  halo2.material = haloMat.clone();
  halo2.material.opacity = 0.2;
  halo2.position.z = 5.8;
  bank.add(halo2);

  const mouthMat = new THREE.MeshBasicMaterial({ color: 0x031113, transparent: true, opacity: 0.9 });
  const mouth = new THREE.Mesh(new THREE.CircleGeometry(1.34, 32), mouthMat);
  mouth.position.z = 8.45;
  mouth.rotation.x = Math.PI;
  bank.add(mouth);

  const lip = new THREE.Mesh(new THREE.TorusGeometry(1.42, 0.11, 6, 48), new THREE.MeshBasicMaterial({ color: 0x8affdf, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false }));
  lip.position.z = 8.47;
  bank.add(lip);

  const glowPositions = [];
  for (let i = 0; i < 16; i += 1) {
    const a = i * 2.39;
    const z = -6 + (i / 16) * 13.2;
    const radius = 1.5 + Math.sin(i * 1.2) * 0.55;
    glowPositions.push(new THREE.Vector3(Math.cos(a) * radius, Math.sin(a) * radius * 1.2, z));
  }
  glowPositions.push(new THREE.Vector3(0, 0, 8.8), new THREE.Vector3(1.8, 1.4, 6.3), new THREE.Vector3(-1.8, -1.2, 6.2));
  bank.add(createGlowPoints(glowPositions, 0x8dffe6, 0.78, glowTexture, 0.92));

  const tentacles = new THREE.Group();
  tentacles.position.z = -2.2;
  bank.add(tentacles);
  const rng = mulberry32(seed + 21);
  for (let i = 0; i < 11; i += 1) {
    const a = (i / 11) * TAU;
    const length = range(rng, 9, 18);
    const points = [];
    for (let s = 0; s < 6; s += 1) {
      const t = s / 5;
      points.push(new THREE.Vector3(
        Math.cos(a) * (1.2 + Math.sin(t * 3.2 + i) * 1.4) * (1 - t * 0.22),
        Math.sin(a) * (1.1 + Math.cos(t * 2.6 + i) * 0.8) * (1 - t * 0.2) - t * length * 0.5,
        -t * length
      ));
    }
    const curve = makeCurve(points);
    const material = tentacleMaterial(0x0b3739, 0x4fffd6, range(rng, 0.32, 0.55), i * 0.9);
    material.onBeforeCompile = (shader) => {
      shader.uniforms.uTime = timeUniform;
      shader.uniforms.uPhase = { value: i * 0.9 };
      shader.vertexShader = shader.vertexShader
        .replace('#include <common>', '#include <common>\nuniform float uTime;\nuniform float uPhase;')
        .replace(
          '#include <begin_vertex>',
          `#include <begin_vertex>
          float sway = sin(position.z * 0.38 + uTime * 1.3 + uPhase) * 0.15 * (0.25 + abs(position.z) * 0.035);
          transformed.x += sway;
          transformed.y += cos(position.z * 0.22 + uTime * 0.85 + uPhase) * 0.1;`
        );
      material.userData.shader = shader;
    };
    const tentacle = new THREE.Mesh(new THREE.TubeGeometry(curve, 40, range(rng, 0.045, 0.12), 5, false), material);
    tentacles.add(tentacle);
  }

  const hornMat = new THREE.MeshStandardMaterial({ color: 0x102d33, roughness: 0.3, metalness: 0.55, emissive: 0x052226, emissiveIntensity: 0.5 });
  for (let i = 0; i < 4; i += 1) {
    const angle = Math.PI * 0.5 + (i - 1.5) * 0.38;
    const points = [];
    for (let s = 0; s < 5; s += 1) {
      const t = s / 4;
      points.push(new THREE.Vector3(Math.cos(angle) * (2.1 + t * 5.2), Math.sin(angle) * (2.1 + t * 4.3), 4.6 - t * 1.2 - Math.abs(t - 0.5) * 1.8));
    }
    const horn = new THREE.Mesh(new THREE.TubeGeometry(makeCurve(points), 18, 0.14, 5, false), hornMat);
    bank.add(horn);
  }

  attachGlow(bank, glowTexture, 0x74ffdf, 5.6, new THREE.Vector3(0, 0, 8.8), 0.5);
  attachGlow(bank, glowTexture, 0x6cffd7, 2.8, new THREE.Vector3(2.8, 2.2, 5.1), 0.4);
  attachGlow(bank, glowTexture, 0x6cffd7, 2.4, new THREE.Vector3(-3, -2.4, 5.5), 0.34);

  return { root, bank, body, crown, halo, lip };
}

class VeilSovereign {
  constructor(scene, timeUniform, glowTexture) {
    this.species = 'veil';
    this.scene = scene;
    this.center = new THREE.Vector3(-34, -26, 4);
    this.radius = 24;
    this.angle = 0;
    this.speed = 1.05;
    this.position = new THREE.Vector3();
    this.direction = new THREE.Vector3(0, 0, 1);
    this.lookTarget = new THREE.Vector3();
    const built = buildVeil(timeUniform, glowTexture, 3);
    this.root = built.root;
    this.bank = built.bank;
    this.crown = built.crown;
    this.halo = built.halo;
    this.lip = built.lip;
    this.root.scale.setScalar(1.08);
    scene.add(this.root);
    this.update(0, 0, new THREE.Vector3());
  }

  get scanPosition() {
    return this.root.position;
  }

  update(dt, time, player) {
    this.angle += dt * (this.speed / this.radius);
    const y = -26 + Math.sin(time * 0.17) * 1.4 + Math.sin(time * 0.41 + 1.2) * 0.35;
    this.position.set(
      this.center.x + Math.cos(this.angle) * this.radius,
      y,
      this.center.z + Math.sin(this.angle) * this.radius
    );
    this.direction.set(-Math.sin(this.angle), Math.cos(time * 0.21) * 0.035, Math.cos(this.angle)).normalize();
    this.root.position.copy(this.position);
    this.lookTarget.copy(this.position).add(this.direction);
    this.root.lookAt(this.lookTarget);
    this.bank.rotation.z = Math.sin(time * 0.23) * 0.13;
    this.bank.rotation.x = Math.sin(time * 0.31 + 1.5) * 0.045;
    this.bank.position.y = Math.sin(time * 0.55) * 0.5;
    this.crown.rotation.z = Math.sin(time * 0.27) * 0.06;
    this.halo.scale.setScalar(1 + Math.sin(time * 0.6) * 0.025);
    this.lip.material.opacity = 0.65 + Math.sin(time * 0.9) * 0.2;
  }
}

class RiftHunter {
  constructor(scene, timeUniform, glowTexture, onAttack) {
    this.species = 'rift';
    this.scene = scene;
    this.onAttack = onAttack;
    this.root = new THREE.Group();
    this.bank = new THREE.Group();
    this.root.add(this.bank);
    this.position = new THREE.Vector3(18, -44, -34);
    this.center = new THREE.Vector3(32, -44, -54);
    this.radius = 27;
    this.angle = 1.9;
    this.patrolSpeed = 2.3;
    this.state = 'patrol';
    this.stateTime = 0;
    this.chargeCooldown = 7;
    this.fleeTime = 0;
    this.direction = new THREE.Vector3(0, 0, 1);
    this.target = new THREE.Vector3();
    this.attackFlash = 0;
    this.jaw = null;
    this.petals = [];
    this.eyes = [];
    this.mouthGlow = null;
    this.glowTexture = glowTexture;
    this.build(timeUniform, glowTexture);
    this.root.position.copy(this.position);
    scene.add(this.root);
  }

  get scanPosition() {
    return this.root.position;
  }

  build(timeUniform, glowTexture) {
    const mat = bodyMaterial(0x0b2228, 8);
    mat.color = new THREE.Color(0x102a30);
    mat.metalness = 0.58;
    mat.roughness = 0.28;
    mat.emissive = new THREE.Color(0x1d0d08);
    mat.emissiveIntensity = 0.6;
    mat.onBeforeCompile = (shader) => {
      shader.uniforms.uTime = timeUniform;
      shader.uniforms.uPhase = { value: 4.1 };
      shader.vertexShader = shader.vertexShader
        .replace('#include <common>', BODY_VERTEX)
        .replace('#include <begin_vertex>', BODY_WAVE);
      shader.fragmentShader = shader.fragmentShader
        .replace('#include <common>', BODY_FRAGMENT)
        .replace('#include <emissivemap_fragment>', BODY_FRAGMENT_PATCH);
      mat.userData.shader = shader;
    };

    const geometry = createLoftGeometry({
      length: 14.5,
      segments: 38,
      radial: 16,
      seed: 8,
      ridge: 0.085,
      profile: (t) => {
        const head = Math.pow(Math.sin(Math.PI * Math.min(1, t * 1.06)), 0.48);
        const taper = 0.35 + head * 2.15;
        return [taper * (1.15 - t * 0.3), taper * (0.72 - t * 0.1)];
      },
    });
    const body = new THREE.Mesh(geometry, mat);
    this.bank.add(body);

    const wingMat = finMaterial(0x0a242b, 0xffa06f, 0.62, 1.2);
    wingMat.uniforms.uTime = timeUniform;
    const wingGeo = createFinGeometry({ span: 10.5, chord: 6.2, sweep: 3.8, lift: 1.35, droop: 1.6, segments: 30, chordSegments: 9, scallop: 0.08 });
    const wingR = new THREE.Mesh(wingGeo, wingMat);
    wingR.position.set(1.4, 0.3, 1.1);
    wingR.rotation.z = -0.06;
    wingR.rotation.y = 0.15;
    this.bank.add(wingR);
    const wingL = new THREE.Mesh(wingGeo, wingMat);
    wingL.scale.x = -1;
    wingL.position.set(-1.4, 0.3, 1.1);
    wingL.rotation.z = 0.06;
    wingL.rotation.y = -0.15;
    this.bank.add(wingL);

    const lowerMat = finMaterial(0x0a2027, 0xff6e50, 0.48, 2.4);
    lowerMat.uniforms.uTime = timeUniform;
    const lowerGeo = createFinGeometry({ span: 6.8, chord: 3.2, sweep: 2.2, lift: 0.55, droop: 1.0, segments: 22, chordSegments: 7 });
    const lowerR = new THREE.Mesh(lowerGeo, lowerMat);
    lowerR.position.set(1.0, -0.8, -2.4);
    lowerR.rotation.z = -0.42;
    lowerR.rotation.y = 0.3;
    this.bank.add(lowerR);
    const lowerL = new THREE.Mesh(lowerGeo, lowerMat);
    lowerL.scale.x = -1;
    lowerL.position.set(-1.0, -0.8, -2.4);
    lowerL.rotation.z = 0.42;
    lowerL.rotation.y = -0.3;
    this.bank.add(lowerL);

    const tailMat = tentacleMaterial(0x0b2227, 0xff8d62, 0.6, 3.2);
    tailMat.onBeforeCompile = (shader) => {
      shader.uniforms.uTime = timeUniform;
      shader.uniforms.uPhase = { value: 2.6 };
      shader.vertexShader = shader.vertexShader
        .replace('#include <common>', '#include <common>\nuniform float uTime;\nuniform float uPhase;')
        .replace(
          '#include <begin_vertex>',
          `#include <begin_vertex>
          float sway = sin(position.z * 0.3 + uTime * 1.15 + uPhase) * 0.2 * (0.2 + abs(position.z) * 0.06);
          transformed.x += sway;
          transformed.y += cos(position.z * 0.25 + uTime * 0.72 + uPhase) * 0.12;`
        );
    };
    for (let side = -1; side <= 1; side += 2) {
      const points = [];
      for (let i = 0; i < 6; i += 1) {
        const t = i / 5;
        points.push(new THREE.Vector3(side * (0.3 + t * 2.4), Math.sin(t * 2.2) * 0.5 - t * 0.6, -7 - t * 9));
      }
      this.bank.add(new THREE.Mesh(new THREE.TubeGeometry(makeCurve(points), 30, 0.13, 5, false), tailMat));
    }

    const mouth = new THREE.Group();
    mouth.position.z = 7.25;
    this.bank.add(mouth);
    this.jaw = mouth;

    const inner = new THREE.Mesh(new THREE.CircleGeometry(1.25, 28), new THREE.MeshBasicMaterial({ color: 0x02090b, transparent: true, opacity: 0.92 }));
    inner.position.z = 0.03;
    mouth.add(inner);

    const petalGeo = createPetalGeometry(2.7, 1.8);
    const petalMat = finMaterial(0x1a0c0b, 0xff8c5e, 0.55, 3.7);
    petalMat.uniforms.uTime = timeUniform;
    for (let i = 0; i < 4; i += 1) {
      const angle = (i / 4) * TAU + Math.PI * 0.25;
      const pivot = new THREE.Group();
      pivot.position.set(Math.cos(angle) * 1.05, Math.sin(angle) * 0.86, 0);
      const petal = new THREE.Mesh(petalGeo, petalMat);
      petal.rotation.z = angle;
      pivot.add(petal);
      mouth.add(pivot);
      this.petals.push({ pivot, angle, base: new THREE.Vector3(Math.cos(angle) * 1.05, Math.sin(angle) * 0.86, 0) });
    }

    const teethGeo = new THREE.ConeGeometry(0.09, 0.7, 5);
    const teethMat = new THREE.MeshStandardMaterial({ color: 0xd2d9ca, roughness: 0.38, metalness: 0.1, emissive: 0x2c0d04, emissiveIntensity: 0.35 });
    const teeth = new THREE.InstancedMesh(teethGeo, teethMat, 18);
    const dummy = new THREE.Object3D();
    for (let i = 0; i < 18; i += 1) {
      const a = (i / 18) * TAU;
      dummy.position.set(Math.cos(a) * 1.05, Math.sin(a) * 0.86, 0.2);
      dummy.rotation.set(Math.PI / 2, 0, -a);
      dummy.updateMatrix();
      teeth.setMatrixAt(i, dummy.matrix);
    }
    teeth.instanceMatrix.needsUpdate = true;
    mouth.add(teeth);

    const eyePositions = [];
    for (let side = -1; side <= 1; side += 2) {
      for (let i = 0; i < 3; i += 1) {
        eyePositions.push(new THREE.Vector3(side * (0.8 + i * 0.34), 1.25 - i * 0.17, 4.8 - i * 0.9));
      }
    }
    this.eyes = eyePositions;
    this.bank.add(createGlowPoints(eyePositions, 0xff9a66, 0.52, glowTexture, 0.9));

    const ridgePositions = [];
    for (let i = 0; i < 8; i += 1) {
      const t = i / 7;
      ridgePositions.push(new THREE.Vector3(0, 1.3 + Math.sin(t * Math.PI) * 0.8, 3.8 - t * 10));
    }
    this.bank.add(createGlowPoints(ridgePositions, 0xffb27f, 0.28, glowTexture, 0.55));

    this.mouthGlow = attachGlow(mouth, glowTexture, 0xff8459, 5.2, new THREE.Vector3(0, 0, 0.4), 0.42);
    attachGlow(this.bank, glowTexture, 0xff6b45, 3.0, new THREE.Vector3(0, 1.4, 2.2), 0.25);
  }

  scare() {
    this.fleeTime = 5.5;
    this.state = 'flee';
    this.stateTime = 0;
    this.chargeCooldown = Math.max(this.chargeCooldown, 4.5);
  }

  update(dt, time, player, playerVelocity) {
    this.stateTime += dt;
    this.chargeCooldown -= dt;
    this.fleeTime -= dt;
    const toPlayer = new THREE.Vector3().subVectors(player, this.position);
    const distance = toPlayer.length();

    if (this.fleeTime > 0) {
      this.state = 'flee';
    } else if (this.state === 'flee' && this.fleeTime <= 0) {
      this.state = 'patrol';
      this.stateTime = 0;
      this.chargeCooldown = 6;
    } else if (this.state === 'patrol' && distance < 54 && this.chargeCooldown <= 0) {
      this.state = 'stalk';
      this.stateTime = 0;
    } else if (this.state === 'stalk') {
      if (distance > 75) {
        this.state = 'patrol';
        this.stateTime = 0;
      } else if (this.stateTime > 4.8 && distance < 55) {
        this.state = 'charge';
        this.stateTime = 0;
        this.chargeTarget = player.clone();
        this.chargeFrom = this.position.clone();
      }
    } else if (this.state === 'charge') {
      if (this.stateTime > 3.2) {
        this.state = 'retreat';
        this.stateTime = 0;
        this.chargeCooldown = 9;
      }
      if (distance < 4.4 && this.stateTime < 2.8) {
        this.onAttack?.(this);
        this.state = 'retreat';
        this.stateTime = 0;
        this.chargeCooldown = 10;
      }
    } else if (this.state === 'retreat' && this.stateTime > 3.5) {
      this.state = 'patrol';
      this.stateTime = 0;
      this.chargeCooldown = 6.5;
    }

    let desired = new THREE.Vector3();
    let speed = this.patrolSpeed;
    if (this.state === 'patrol') {
      this.angle += dt * (this.patrolSpeed / this.radius);
      desired.set(
        this.center.x + Math.cos(this.angle) * this.radius,
        this.center.y + Math.sin(time * 0.23) * 5,
        this.center.z + Math.sin(this.angle) * this.radius
      );
      desired.sub(this.position);
      speed = 3.3;
    } else if (this.state === 'stalk') {
      const tangent = new THREE.Vector3(-toPlayer.z, 0, toPlayer.x).normalize();
      const orbit = player.clone().add(tangent.multiplyScalar(24)).add(new THREE.Vector3(0, 4, 0));
      desired.subVectors(orbit, this.position);
      speed = 5.2;
    } else if (this.state === 'charge') {
      const target = player.clone();
      if (this.stateTime < 0.8) {
        target.copy(this.chargeTarget);
      }
      desired.subVectors(target, this.position);
      speed = 15.5;
    } else if (this.state === 'retreat') {
      const away = new THREE.Vector3().subVectors(this.position, player).normalize();
      desired.copy(away).multiplyScalar(18);
      speed = 9;
    } else if (this.state === 'flee') {
      const away = new THREE.Vector3().subVectors(this.position, player).normalize();
      desired.copy(away).multiplyScalar(24);
      speed = 13;
    }

    if (desired.lengthSq() > 0.001) desired.normalize();
    const targetVelocity = desired.multiplyScalar(speed);
    this.position.addScaledVector(targetVelocity, dt);
    this.position.y = clamp(this.position.y, -102, -8);

    const lookDirection = targetVelocity.lengthSq() > 0.1 ? targetVelocity.clone().normalize() : toPlayer.normalize();
    this.direction.lerp(lookDirection, 1 - Math.exp(-3.2 * dt)).normalize();
    this.root.position.copy(this.position);
    this.root.lookAt(this.position.clone().add(this.direction));

    const banking = clamp(-this.direction.x * 0.45 + Math.sin(time * 0.9) * 0.04, -0.55, 0.55);
    this.bank.rotation.z = damp(this.bank.rotation.z, banking, 2.2, dt);
    this.bank.rotation.x = damp(this.bank.rotation.x, this.state === 'charge' ? -0.16 : Math.sin(time * 0.4) * 0.035, 2, dt);

    const jawOpen = this.state === 'charge' ? 1 : this.state === 'stalk' ? 0.24 + Math.sin(time * 2) * 0.08 : 0.08;
    const jawAmount = damp(this.jaw.rotation.x, jawOpen, 4, dt);
    this.petals.forEach(({ pivot, angle, base }, i) => {
      const direction = new THREE.Vector3(Math.cos(angle), Math.sin(angle), 0.25).normalize();
      pivot.position.copy(base).addScaledVector(direction, jawAmount * 0.7);
      pivot.rotation.z = angle + jawAmount * 0.3 * Math.sin(angle);
      pivot.rotation.x = jawAmount * 0.72;
      pivot.rotation.y = jawAmount * 0.2 * Math.cos(angle);
    });
    if (this.mouthGlow) this.mouthGlow.material.opacity = 0.25 + jawAmount * 0.55;

    this.attackFlash = Math.max(0, this.attackFlash - dt);
  }
}

function buildSpireDrifter(timeUniform, glowTexture, seed = 4) {
  const root = new THREE.Group();
  const bank = new THREE.Group();
  root.add(bank);
  const rng = mulberry32(seed);

  const shellPoints = [];
  for (let i = 0; i <= 74; i += 1) {
    const t = i / 74;
    const a = t * Math.PI * 6.2;
    const r = 0.1 + t * 2.25;
    shellPoints.push(new THREE.Vector3(Math.cos(a) * r, Math.sin(a) * r * 0.82, t * 0.9 - 0.45));
  }
  const shellMat = new THREE.MeshPhysicalMaterial({
    color: 0xb77d61,
    roughness: 0.24,
    metalness: 0.35,
    clearcoat: 0.8,
    clearcoatRoughness: 0.2,
    emissive: 0x2a0c08,
    emissiveIntensity: 0.35,
    iridescence: 0.8,
    iridescenceIOR: 1.35,
    iridescenceThicknessRange: [140, 460],
  });
  const shell = new THREE.Mesh(new THREE.TubeGeometry(makeCurve(shellPoints), 90, 0.28, 7, false), shellMat);
  shell.scale.set(1, 1, 0.9);
  bank.add(shell);

  const bodyMat = new THREE.MeshStandardMaterial({ color: 0x8c4e42, roughness: 0.5, metalness: 0.12, emissive: 0x45110c, emissiveIntensity: 0.5 });
  const body = new THREE.Mesh(new THREE.SphereGeometry(0.85, 16, 12), bodyMat);
  body.scale.set(1, 0.8, 1.2);
  body.position.set(2.2, 0, 0.35);
  bank.add(body);

  const armMat = tentacleMaterial(0xb66e54, 0xffb37b, 0.7, seed);
  armMat.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = timeUniform;
    shader.uniforms.uPhase = { value: seed * 1.1 };
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nuniform float uTime;\nuniform float uPhase;')
      .replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
        float sway = sin(position.z * 1.2 + uTime * 2.0 + uPhase) * 0.09;
        transformed.x += sway;
        transformed.y += cos(position.z * 0.9 + uTime * 1.6 + uPhase) * 0.06;`
      );
  };
  for (let i = 0; i < 7; i += 1) {
    const a = (i / 7) * TAU;
    const points = [];
    for (let s = 0; s < 5; s += 1) {
      const t = s / 4;
      points.push(new THREE.Vector3(2.3 + Math.cos(a) * t * 1.8 + Math.sin(t * 3 + i) * 0.25, Math.sin(a) * t * 1.4 + Math.sin(t * 4 + i) * 0.2, 0.6 + t * 2.1));
    }
    const arm = new THREE.Mesh(new THREE.TubeGeometry(makeCurve(points), 20, 0.035, 4, false), armMat);
    bank.add(arm);
  }

  const core = attachGlow(bank, glowTexture, 0xffa56f, 2.3, new THREE.Vector3(2.3, 0, 0.9), 0.65);
  const rim = new THREE.Mesh(new THREE.TorusGeometry(2.45, 0.025, 4, 48), new THREE.MeshBasicMaterial({ color: 0xffc48e, transparent: true, opacity: 0.42, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false }));
  rim.rotation.y = Math.PI / 2;
  rim.position.x = 0.4;
  bank.add(rim);

  return { root, bank, shell, core, rim, rng };
}

class SpireDrifters {
  constructor(scene, timeUniform, glowTexture) {
    this.species = 'spire';
    this.items = [];
    this.center = new THREE.Vector3(-35, -55, -15);
    this.root = new THREE.Group();
    scene.add(this.root);
    const rng = mulberry32(17);
    for (let i = 0; i < 5; i += 1) {
      const built = buildSpireDrifter(timeUniform, glowTexture, 40 + i);
      const angle = (i / 5) * TAU;
      const radius = range(rng, 2, 8);
      built.root.position.set(
        this.center.x + Math.cos(angle) * radius,
        this.center.y + range(rng, -3, 5),
        this.center.z + Math.sin(angle) * radius
      );
      built.root.scale.setScalar(range(rng, 0.72, 1.25));
      built.base = built.root.position.clone();
      built.phase = range(rng, 0, TAU);
      built.speed = range(rng, 0.08, 0.2);
      built.flee = 0;
      this.root.add(built.root);
      this.items.push(built);
    }
  }

  get scanPosition() {
    return this.center;
  }

  update(dt, time, player) {
    for (const item of this.items) {
      const toPlayer = new THREE.Vector3().subVectors(player, item.root.position);
      const distance = toPlayer.length();
      item.flee = Math.max(0, item.flee - dt);
      if (distance < 8) item.flee = 2.2;
      const fleeDirection = toPlayer.clone().normalize().multiplyScalar(-1);
      if (item.flee > 0) {
        item.root.position.addScaledVector(fleeDirection, dt * 2.3);
      } else {
        item.root.position.x = item.base.x + Math.sin(time * item.speed + item.phase) * 1.7;
        item.root.position.y = item.base.y + Math.sin(time * item.speed * 1.7 + item.phase) * 1.3;
        item.root.position.z = item.base.z + Math.cos(time * item.speed * 0.8 + item.phase) * 1.5;
      }
      item.root.rotation.y += dt * 0.15;
      item.root.rotation.z = Math.sin(time * 0.4 + item.phase) * 0.12;
      item.bank.position.y = Math.sin(time * 0.8 + item.phase) * 0.15;
      item.core.material.opacity = 0.45 + Math.sin(time * 0.9 + item.phase) * 0.18;
      item.rim.rotation.z += dt * 0.22;
    }
  }
}

function createShardGeometry() {
  const geometry = new THREE.TetrahedronGeometry(0.32, 0);
  geometry.scale(1.0, 0.45, 2.6);
  return geometry;
}

class GlassShoals {
  constructor(scene, glowTexture) {
    this.species = 'shoal';
    this.schools = [];
    this.root = new THREE.Group();
    scene.add(this.root);
    const anchors = [
      new THREE.Vector3(15, -7, 21),
      new THREE.Vector3(-29, -24, 8),
      new THREE.Vector3(43, -40, -54),
    ];
    const counts = [64, 54, 46];
    const shardGeo = createShardGeometry();
    const shardMat = new THREE.MeshStandardMaterial({
      color: 0xa7ffff,
      emissive: 0x2be0d8,
      emissiveIntensity: 1.4,
      roughness: 0.1,
      metalness: 0.22,
      transparent: true,
      opacity: 0.72,
      depthWrite: false,
      side: THREE.DoubleSide,
      toneMapped: false,
    });
    const rng = mulberry32(51);

    anchors.forEach((anchor, schoolIndex) => {
      const count = counts[schoolIndex];
      const mesh = new THREE.InstancedMesh(shardGeo, shardMat, count);
      mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      mesh.frustumCulled = false;
      this.root.add(mesh);

      const positions = [];
      const velocities = [];
      for (let i = 0; i < count; i += 1) {
        const pos = anchor.clone().add(new THREE.Vector3(range(rng, -6, 6), range(rng, -3, 3), range(rng, -6, 6)));
        positions.push(pos);
        velocities.push(new THREE.Vector3(range(rng, -0.4, 0.4), range(rng, -0.15, 0.15), range(rng, -0.4, 0.4)));
      }
      const glowGeo = new THREE.BufferGeometry().setFromPoints(positions);
      const glow = new THREE.Points(glowGeo, createPointsMaterial(glowTexture, 0x9bffff, 0.48, 0.55));
      glow.frustumCulled = false;
      this.root.add(glow);
      this.schools.push({
        anchor,
        mesh,
        glow,
        positions,
        velocities,
        count,
        phase: schoolIndex * 2.1,
        dummy: new THREE.Object3D(),
        glowPositions: glowGeo.attributes.position,
      });
    });
  }

  get scanPosition() {
    return this.schools[0].anchor;
  }

  update(dt, time, player, predator) {
    for (const school of this.schools) {
      const { anchor, mesh, positions, velocities, count, dummy } = school;
      const toPlayer = new THREE.Vector3().subVectors(player, anchor);
      const playerDistance = toPlayer.length();
      const flee = playerDistance < 13 ? (13 - playerDistance) / 13 : 0;
      const predatorDistance = predator ? predator.position.distanceTo(anchor) : 999;
      const predatorFlee = predatorDistance < 34 ? 1 : 0;
      const swarmTarget = anchor.clone().add(new THREE.Vector3(
        Math.sin(time * 0.16 + school.phase) * 5,
        Math.sin(time * 0.23 + school.phase * 1.7) * 2,
        Math.cos(time * 0.13 + school.phase) * 5
      ));

      for (let i = 0; i < count; i += 1) {
        const pos = positions[i];
        const vel = velocities[i];
        const cohesion = swarmTarget.clone().sub(pos).multiplyScalar(0.09);
        const noise = new THREE.Vector3(
          Math.sin(time * 1.2 + i * 2.4) * 0.7,
          Math.cos(time * 1.7 + i * 1.3) * 0.35,
          Math.cos(time * 1.1 + i * 1.7) * 0.7
        );
        vel.add(cohesion).addScaledVector(noise, dt);
        if (flee > 0) {
          const away = pos.clone().sub(player).normalize();
          vel.addScaledVector(away, flee * dt * 11);
        }
        if (predatorFlee && predator) {
          const away = pos.clone().sub(predator.position).normalize();
          vel.addScaledVector(away, predatorFlee * dt * 9);
        }
        const separation = new THREE.Vector3();
        for (let j = 0; j < 4; j += 1) {
          const other = positions[(i + j * 7 + 3) % count];
          const delta = pos.clone().sub(other);
          const d = delta.length();
          if (d > 0.01 && d < 1.2) separation.addScaledVector(delta.normalize(), (1.2 - d) * 0.7);
        }
        vel.add(separation);
        vel.clampLength(0.8, 9.5);
        pos.addScaledVector(vel, dt);
        const dist = pos.distanceTo(anchor);
        if (dist > 15) {
          pos.lerp(anchor, dt * 0.5);
          vel.multiplyScalar(0.98);
        }
        dummy.position.copy(pos);
        dummy.lookAt(pos.clone().add(vel));
        dummy.scale.set(1, 0.7 + Math.sin(i + time) * 0.06, 1.6);
        dummy.updateMatrix();
        mesh.setMatrixAt(i, dummy.matrix);
        school.glowPositions.setXYZ(i, pos.x, pos.y, pos.z);
      }
      mesh.instanceMatrix.needsUpdate = true;
      school.glowPositions.needsUpdate = true;
    }
  }
}

class BellBlooms {
  constructor(scene, glowTexture) {
    this.species = 'bell';
    this.clusters = [];
    this.root = new THREE.Group();
    scene.add(this.root);
    const anchors = [
      new THREE.Vector3(-18, -18, 25),
      new THREE.Vector3(31, -32, -12),
      new THREE.Vector3(-6, -64, -55),
    ];
    const bellGeo = new THREE.SphereGeometry(0.46, 14, 9, 0, TAU, 0, Math.PI * 0.56);
    bellGeo.scale(1, 1.2, 1);
    const bellMat = new THREE.MeshStandardMaterial({
      color: 0xc2b7ff,
      emissive: 0x6c4bff,
      emissiveIntensity: 1.2,
      roughness: 0.18,
      metalness: 0.1,
      transparent: true,
      opacity: 0.66,
      depthWrite: false,
      side: THREE.DoubleSide,
      toneMapped: false,
    });
    const rng = mulberry32(88);

    anchors.forEach((anchor, clusterIndex) => {
      const count = 26;
      const mesh = new THREE.InstancedMesh(bellGeo, bellMat, count);
      mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      mesh.frustumCulled = false;
      this.root.add(mesh);
      const data = [];
      for (let i = 0; i < count; i += 1) {
        data.push({
          offset: new THREE.Vector3(range(rng, -4.5, 4.5), range(rng, -3.5, 3.5), range(rng, -4.5, 4.5)),
          phase: range(rng, 0, TAU),
          speed: range(rng, 0.25, 0.7),
          scale: range(rng, 0.7, 1.4),
        });
      }
      const glowGeo = new THREE.BufferGeometry();
      glowGeo.setAttribute('position', new THREE.Float32BufferAttribute(new Float32Array(count * 3), 3));
      const glow = new THREE.Points(glowGeo, createPointsMaterial(glowTexture, 0xbb9dff, 0.9, 0.55));
      glow.frustumCulled = false;
      this.root.add(glow);
      this.clusters.push({
        anchor,
        mesh,
        glow,
        data,
        count,
        dummy: new THREE.Object3D(),
        glowPositions: glowGeo.attributes.position,
        phase: clusterIndex * 1.8,
      });
    });
  }

  get scanPosition() {
    return this.clusters[0].anchor;
  }

  update(dt, time) {
    for (const cluster of this.clusters) {
      const { anchor, mesh, data, count, dummy } = cluster;
      for (let i = 0; i < count; i += 1) {
        const item = data[i];
        const pulse = 1 + Math.sin(time * item.speed * 2.2 + item.phase) * 0.14;
        dummy.position.set(
          anchor.x + item.offset.x + Math.sin(time * 0.18 + item.phase) * 0.6,
          anchor.y + item.offset.y + Math.sin(time * item.speed + item.phase) * 1.4,
          anchor.z + item.offset.z + Math.cos(time * 0.15 + item.phase) * 0.6
        );
        dummy.rotation.set(Math.sin(time * 0.2 + item.phase) * 0.2, time * 0.08 + item.phase, Math.cos(time * 0.18 + item.phase) * 0.2);
        dummy.scale.setScalar(item.scale * pulse);
        dummy.updateMatrix();
        mesh.setMatrixAt(i, dummy.matrix);
        cluster.glowPositions.setXYZ(i, dummy.position.x, dummy.position.y + 0.2, dummy.position.z);
      }
      mesh.instanceMatrix.needsUpdate = true;
      cluster.glowPositions.needsUpdate = true;
    }
  }
}

export class CreatureWorld {
  constructor(scene, timeUniform, glowTexture, { onAttack } = {}) {
    this.scene = scene;
    this.veil = new VeilSovereign(scene, timeUniform, glowTexture);
    this.rift = new RiftHunter(scene, timeUniform, glowTexture, onAttack);
    this.spires = new SpireDrifters(scene, timeUniform, glowTexture);
    this.shoals = new GlassShoals(scene, glowTexture);
    this.bells = new BellBlooms(scene, glowTexture);
    this.all = [this.veil, this.rift, this.spires, this.shoals, this.bells];
    this.registry = {
      veil: this.veil,
      rift: this.rift,
      spire: this.spires,
      shoal: this.shoals,
      bell: this.bells,
    };
  }

  update(dt, time, player, playerVelocity) {
    this.veil.update(dt, time, player);
    this.rift.update(dt, time, player, playerVelocity);
    this.spires.update(dt, time, player);
    this.shoals.update(dt, time, player, this.rift);
    this.bells.update(dt, time);
  }

  pulse(playerPosition) {
    this.rift.scare();
    const targets = [];
    for (const [key, value] of Object.entries(this.registry)) {
      targets.push({ key, position: value.scanPosition.clone(), species: SPECIES[key] });
    }
    return targets;
  }

  getTargets() {
    return Object.entries(this.registry).map(([key, value]) => ({
      key,
      species: SPECIES[key],
      position: value.scanPosition.clone(),
    }));
  }
}

import * as THREE from 'three';
import {
  TAU,
  clamp,
  damp,
  fbm,
  lerp,
  makeGlowTexture,
  mulberry32,
  range,
  terrainHeight,
  createGlowSprite,
  createPointsMaterial,
} from './utils.js';

const SUN_DIR = new THREE.Vector3(-0.32, 0.82, 0.47).normalize();
const SHALLOW_FOG = new THREE.Color(0x0a4d57);
const MID_FOG = new THREE.Color(0x052e37);
const DEEP_FOG = new THREE.Color(0x010b11);

function createSkyDome(timeUniform) {
  const geometry = new THREE.SphereGeometry(430, 32, 24);
  const material = new THREE.ShaderMaterial({
    uniforms: {
      uTime: timeUniform,
      uTop: { value: new THREE.Color(0x03161e) },
      uBottom: { value: new THREE.Color(0x062e36) },
      uSunDir: { value: SUN_DIR.clone() },
      uGlow: { value: new THREE.Color(0x6bffe3) },
    },
    vertexShader: `
      varying vec3 vPos;
      void main() {
        vPos = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 uTop;
      uniform vec3 uBottom;
      uniform vec3 uSunDir;
      uniform vec3 uGlow;
      varying vec3 vPos;
      void main() {
        vec3 dir = normalize(vPos);
        float h = smoothstep(-0.55, 0.85, dir.y);
        vec3 col = mix(uBottom, uTop, h);
        float sun = pow(max(dot(dir, normalize(uSunDir)), 0.0), 32.0);
        col += uGlow * sun * 0.16;
        float horizon = exp(-abs(dir.y) * 8.0) * 0.12;
        col += uGlow * horizon;
        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    toneMapped: true,
  });
  const dome = new THREE.Mesh(geometry, material);
  dome.renderOrder = -20;
  return dome;
}

function createOceanSurface(timeUniform) {
  const geometry = new THREE.PlaneGeometry(880, 880, 150, 150);
  geometry.rotateX(-Math.PI / 2);
  const material = new THREE.ShaderMaterial({
    uniforms: {
      uTime: timeUniform,
      uSunDir: { value: SUN_DIR.clone() },
      uSkyColor: { value: new THREE.Color(0xb9fff1) },
      uHorizonColor: { value: new THREE.Color(0x4cd5cc) },
      uDeepColor: { value: new THREE.Color(0x02141b) },
      uGlowColor: { value: new THREE.Color(0x8affdf) },
    },
    vertexShader: `
      uniform float uTime;
      varying vec3 vWorldPosition;
      varying vec3 vNormalW;
      varying vec2 vUv;
      void main() {
        vec3 p = position;
        vec4 wp = modelMatrix * vec4(p, 1.0);
        float w1 = sin(wp.x * 0.13 + uTime * 0.56) * 0.42;
        float w2 = sin(wp.z * 0.11 - uTime * 0.41) * 0.36;
        float w3 = sin((wp.x + wp.z) * 0.21 + uTime * 0.84) * 0.11;
        float w4 = sin((wp.x - wp.z) * 0.34 - uTime * 0.63) * 0.055;
        wp.y += w1 + w2 + w3 + w4;
        float dx = cos(wp.x * 0.13 + uTime * 0.56) * 0.13 * 0.42
                 + cos((wp.x + wp.z) * 0.21 + uTime * 0.84) * 0.21 * 0.11
                 + cos((wp.x - wp.z) * 0.34 - uTime * 0.63) * 0.34 * 0.055;
        float dz = cos(wp.z * 0.11 - uTime * 0.41) * 0.11 * 0.36
                 + cos((wp.x + wp.z) * 0.21 + uTime * 0.84) * 0.21 * 0.11
                 - cos((wp.x - wp.z) * 0.34 - uTime * 0.63) * 0.34 * 0.055;
        vNormalW = normalize(vec3(-dx, 1.0, -dz));
        vWorldPosition = wp.xyz;
        vUv = uv;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: `
      uniform float uTime;
      uniform vec3 uSunDir;
      uniform vec3 uSkyColor;
      uniform vec3 uHorizonColor;
      uniform vec3 uDeepColor;
      uniform vec3 uGlowColor;
      varying vec3 vWorldPosition;
      varying vec3 vNormalW;
      varying vec2 vUv;

      float hash(vec2 p) {
        p = fract(p * vec2(123.34, 456.21));
        p += dot(p, p + 45.32);
        return fract(p.x * p.y);
      }

      float noise(vec2 p) {
        vec2 i = floor(p);
        vec2 f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        float a = hash(i);
        float b = hash(i + vec2(1.0, 0.0));
        float c = hash(i + vec2(0.0, 1.0));
        float d = hash(i + vec2(1.0, 1.0));
        return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
      }

      float caustic(vec2 p, float t) {
        float v = 0.0;
        for (int i = 0; i < 3; i++) {
          p = p * 1.55 + vec2(sin(t * 0.17 + float(i)), cos(t * 0.13 + float(i)));
          v += abs(sin(p.x + sin(p.y + t * 0.33)));
        }
        return pow(1.0 - clamp(v / 3.0, 0.0, 1.0), 4.0);
      }

      void main() {
        vec3 N = normalize(vNormalW);
        vec3 V = normalize(cameraPosition - vWorldPosition);
        vec3 L = normalize(uSunDir);
        bool underwater = cameraPosition.y < 0.0;
        vec3 col;

        if (underwater) {
          float upness = clamp(-V.y, 0.0, 1.0);
          float window = smoothstep(0.03, 0.58, upness);
          vec3 sky = mix(uHorizonColor, uSkyColor, smoothstep(0.02, 0.92, upness));
          float ripple = caustic(vWorldPosition.xz * 0.055, uTime);
          float wave = sin(vWorldPosition.x * 0.22 + sin(vWorldPosition.z * 0.15 + uTime * 0.3) * 1.2);
          sky += uGlowColor * ripple * (0.14 + wave * 0.035) * window;
          vec3 reflected = uDeepColor * 0.3;
          col = mix(reflected, sky, window);
          vec3 R = reflect(-L, N);
          float spec = pow(max(dot(R, V), 0.0), 150.0);
          col += vec3(1.0, 0.94, 0.8) * spec * 2.2 * window;
          float shimmer = smoothstep(0.72, 1.0, sin(vWorldPosition.x * 0.65 + sin(vWorldPosition.z * 0.2 + uTime) * 1.3) * 0.5 + 0.5);
          col += uGlowColor * shimmer * 0.022;
        } else {
          vec3 R = reflect(-V, N);
          float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);
          col = mix(uDeepColor, uSkyColor, fresnel);
          float spec = pow(max(dot(R, L), 0.0), 220.0);
          col += vec3(1.0, 0.95, 0.82) * spec * 4.0;
        }

        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
    side: THREE.DoubleSide,
    depthWrite: true,
    fog: false,
    toneMapped: true,
  });
  const mesh = new THREE.Mesh(geometry, material);
  mesh.renderOrder = -2;
  return mesh;
}

function createTerrain(timeUniform) {
  const size = 520;
  const segments = 140;
  const geometry = new THREE.PlaneGeometry(size, size, segments, segments);
  geometry.rotateX(-Math.PI / 2);
  const position = geometry.attributes.position;
  const colors = [];
  const color = new THREE.Color();

  for (let i = 0; i < position.count; i += 1) {
    const x = position.getX(i);
    const z = position.getZ(i);
    const y = terrainHeight(x, z);
    position.setY(i, y);
    const heightT = clamp((y + 118) / 46, 0, 1);
    const tint = fbm(x * 0.09 + 3, z * 0.09 - 7, 2);
    color.setRGB(
      0.016 + heightT * 0.05 + tint * 0.018,
      0.055 + heightT * 0.19 + tint * 0.05,
      0.07 + heightT * 0.17 + tint * 0.045
    );
    colors.push(color.r, color.g, color.b);
  }
  position.needsUpdate = true;
  geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
  geometry.computeVertexNormals();

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uTime: timeUniform,
      uSunDir: { value: SUN_DIR.clone() },
      uFogColor: { value: new THREE.Color(0x052e37) },
      uFogDensity: { value: 0.011 },
      uGlow: { value: new THREE.Color(0x58ffd9) },
    },
    vertexShader: `
      attribute vec3 color;
      varying vec3 vColor;
      varying vec3 vWorld;
      varying vec3 vNormalW;
      varying float vFogDepth;
      void main() {
        vColor = color;
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vWorld = wp.xyz;
        vNormalW = normalize(mat3(modelMatrix) * normal);
        vec4 mvPosition = viewMatrix * wp;
        vFogDepth = -mvPosition.z;
        gl_Position = projectionMatrix * mvPosition;
      }
    `,
    fragmentShader: `
      uniform float uTime;
      uniform vec3 uSunDir;
      uniform vec3 uFogColor;
      uniform float uFogDensity;
      uniform vec3 uGlow;
      varying vec3 vColor;
      varying vec3 vWorld;
      varying vec3 vNormalW;
      varying float vFogDepth;

      float hash(vec2 p) {
        p = fract(p * vec2(123.34, 456.21));
        p += dot(p, p + 45.32);
        return fract(p.x * p.y);
      }
      float noise(vec2 p) {
        vec2 i = floor(p);
        vec2 f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x), f.y);
      }
      float caustic(vec2 p, float t) {
        float v = 0.0;
        for (int i = 0; i < 3; i++) {
          p = p * 1.63 + vec2(sin(t * 0.14 + float(i)), cos(t * 0.11 + float(i)));
          v += abs(sin(p.x + sin(p.y + t * 0.26)));
        }
        return pow(1.0 - clamp(v / 3.0, 0.0, 1.0), 5.0);
      }

      void main() {
        vec3 N = normalize(vNormalW);
        vec3 L = normalize(uSunDir);
        vec3 V = normalize(cameraPosition - vWorld);
        float diff = max(dot(N, L), 0.0);
        float rim = pow(1.0 - max(dot(N, V), 0.0), 2.4);
        float causticLight = caustic(vWorld.xz * 0.095, uTime);
        float crack = pow(abs(sin(vWorld.x * 0.075 + sin(vWorld.z * 0.052) * 4.0)), 26.0);
        vec3 base = vColor;
        vec3 col = base * (0.16 + diff * 0.75);
        col += vec3(0.055, 0.23, 0.21) * causticLight * (0.22 + diff * 0.3);
        col += uGlow * crack * 0.035;
        col += vec3(0.02, 0.075, 0.08) * rim;
        float fogFactor = 1.0 - exp(-uFogDensity * uFogDensity * vFogDepth * vFogDepth);
        col = mix(col, uFogColor, clamp(fogFactor, 0.0, 1.0));
        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
    vertexColors: true,
    toneMapped: true,
  });
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.y = 0;
  return mesh;
}

function createRocks(seed = 12) {
  const rng = mulberry32(seed);
  const geometry = new THREE.IcosahedronGeometry(1, 0);
  const material = new THREE.MeshStandardMaterial({
    color: 0x0a2024,
    roughness: 0.86,
    metalness: 0.14,
    flatShading: true,
    emissive: 0x031418,
    emissiveIntensity: 0.35,
  });
  const count = 150;
  const mesh = new THREE.InstancedMesh(geometry, material, count);
  const dummy = new THREE.Object3D();
  for (let i = 0; i < count; i += 1) {
    const angle = rng() * TAU;
    const radius = 20 + Math.sqrt(rng()) * 210;
    const x = Math.cos(angle) * radius;
    const z = Math.sin(angle) * radius;
    const y = terrainHeight(x, z);
    const scale = range(rng, 1.2, 8.5) * (rng() > 0.85 ? 2.3 : 1);
    dummy.position.set(x, y + scale * 0.25, z);
    dummy.rotation.set(rng() * TAU, rng() * TAU, rng() * TAU);
    dummy.scale.set(scale, scale * range(rng, 0.45, 1.2), scale * range(rng, 0.7, 1.5));
    dummy.updateMatrix();
    mesh.setMatrixAt(i, dummy.matrix);
  }
  mesh.instanceMatrix.needsUpdate = true;
  return mesh;
}

function createKelp(timeUniform, seed = 31) {
  const rng = mulberry32(seed);
  const geometry = new THREE.PlaneGeometry(1.2, 18, 1, 18);
  geometry.translate(0, 9, 0);
  const material = new THREE.MeshStandardMaterial({
    color: 0x0e3b3c,
    emissive: 0x0a4d49,
    emissiveIntensity: 0.55,
    roughness: 0.62,
    metalness: 0.08,
    side: THREE.DoubleSide,
    transparent: true,
    opacity: 0.76,
  });
  material.onBeforeCompile = (shader) => {
    shader.uniforms.uTime = timeUniform;
    shader.vertexShader = shader.vertexShader
      .replace('#include <common>', '#include <common>\nuniform float uTime;')
      .replace(
        '#include <begin_vertex>',
        `#include <begin_vertex>
        float bend = sin(transformed.y * 0.23 + uTime * 0.62) * 0.11 * transformed.y;
        transformed.x += bend;
        transformed.z += cos(transformed.y * 0.16 + uTime * 0.44) * 0.06 * transformed.y;`
      );
  };
  const count = 55;
  const mesh = new THREE.InstancedMesh(geometry, material, count);
  const dummy = new THREE.Object3D();
  for (let i = 0; i < count; i += 1) {
    const angle = rng() * TAU;
    const radius = 12 + Math.sqrt(rng()) * 185;
    const x = Math.cos(angle) * radius;
    const z = Math.sin(angle) * radius;
    const y = terrainHeight(x, z);
    const scale = range(rng, 0.55, 1.6);
    dummy.position.set(x, y - 0.2, z);
    dummy.rotation.set(0, rng() * TAU, 0);
    dummy.scale.set(scale, scale * range(rng, 0.6, 1.25), scale);
    dummy.updateMatrix();
    mesh.setMatrixAt(i, dummy.matrix);
  }
  mesh.instanceMatrix.needsUpdate = true;
  return mesh;
}

function createSpire(timeUniform, glowTexture) {
  const group = new THREE.Group();
  group.position.set(2, -122, -78);
  const profile = [];
  for (let i = 0; i <= 28; i += 1) {
    const t = i / 28;
    const y = t * 91;
    const radius = 4 + Math.sin(t * Math.PI) * 9.5 + Math.sin(t * 19) * 1.3 + Math.sin(t * 7.2) * 2.6;
    profile.push(new THREE.Vector2(Math.max(0.5, radius), y));
  }
  const material = new THREE.MeshStandardMaterial({
    color: 0x0a252a,
    roughness: 0.74,
    metalness: 0.28,
    emissive: 0x031d20,
    emissiveIntensity: 0.7,
    flatShading: true,
  });
  const spire = new THREE.Mesh(new THREE.LatheGeometry(profile, 18), material);
  spire.rotation.y = 0.4;
  group.add(spire);

  const glowMat = new THREE.MeshBasicMaterial({ color: 0x7affe2, transparent: true, opacity: 0.4, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
  for (let i = 0; i < 4; i += 1) {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(11 - i * 1.2, 0.06, 4, 64), glowMat);
    ring.rotation.x = Math.PI / 2;
    ring.rotation.z = i * 0.4;
    ring.position.y = 37 + i * 12;
    group.add(ring);
  }

  const top = createGlowSprite(glowTexture, 0x9bffe8, 22, 0.48);
  top.position.y = 92;
  group.add(top);

  const topCore = new THREE.Mesh(new THREE.IcosahedronGeometry(1.4, 1), new THREE.MeshBasicMaterial({ color: 0xb4fff1, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false }));
  topCore.position.y = 92;
  group.add(topCore);

  const light = new THREE.PointLight(0x69ffe0, 55, 80, 2);
  light.position.y = 88;
  group.add(light);

  const rng = mulberry32(33);
  const tendrilMat = new THREE.MeshStandardMaterial({ color: 0x0c3336, emissive: 0x0b8e80, emissiveIntensity: 0.5, roughness: 0.45, metalness: 0.2, transparent: true, opacity: 0.72, depthWrite: false });
  for (let i = 0; i < 8; i += 1) {
    const a = (i / 8) * TAU + 0.2;
    const points = [];
    for (let s = 0; s < 8; s += 1) {
      const t = s / 7;
      const radius = 11 + t * 9 + Math.sin(t * 7 + i) * 2;
      points.push(new THREE.Vector3(Math.cos(a + t * 1.6) * radius, 30 + t * 52, Math.sin(a + t * 1.6) * radius));
    }
    const tube = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(points), 34, 0.09 + rng() * 0.08, 4, false), tendrilMat);
    group.add(tube);
  }

  const motesGeo = new THREE.BufferGeometry();
  const positions = [];
  for (let i = 0; i < 60; i += 1) {
    const a = rng() * TAU;
    const r = 6 + rng() * 16;
    positions.push(Math.cos(a) * r, 30 + rng() * 60, Math.sin(a) * r);
  }
  motesGeo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  const motes = new THREE.Points(motesGeo, createPointsMaterial(glowTexture, 0x8affdf, 1.15, 0.7));
  group.add(motes);

  group.userData.topCore = topCore;
  group.userData.topGlow = top;
  group.userData.rings = group.children.filter((child) => child.geometry?.type === 'TorusGeometry');
  return group;
}

function createShafts(timeUniform, seed = 9) {
  const rng = mulberry32(seed);
  const geometry = new THREE.PlaneGeometry(20, 128, 1, 1);
  const group = new THREE.Group();
  const shafts = [];
  for (let i = 0; i < 20; i += 1) {
    const material = new THREE.ShaderMaterial({
      uniforms: {
        uTime: timeUniform,
        uPhase: { value: rng() * TAU },
        uOpacity: { value: range(rng, 0.35, 0.9) },
      },
      vertexShader: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform float uPhase;
        uniform float uOpacity;
        varying vec2 vUv;
        void main() {
          float edge = smoothstep(0.0, 0.2, vUv.x) * smoothstep(1.0, 0.8, vUv.x);
          float fade = smoothstep(0.0, 0.1, vUv.y) * (1.0 - smoothstep(0.5, 1.0, vUv.y));
          float bands = 0.58 + 0.42 * sin(vUv.x * 13.0 + uTime * 0.38 + uPhase);
          float fine = 0.55 + 0.45 * sin(vUv.y * 28.0 - uTime * 0.62 + uPhase * 2.1);
          float alpha = edge * fade * (0.35 + 0.65 * bands * fine) * uOpacity * 0.12;
          gl_FragColor = vec4(vec3(0.57, 1.0, 0.84), alpha);
        }
      `,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
      fog: false,
      toneMapped: false,
    });
    const shaft = new THREE.Mesh(geometry, material);
    const angle = rng() * TAU;
    const radius = 15 + Math.sqrt(rng()) * 115;
    shaft.position.set(Math.cos(angle) * radius, -56, Math.sin(angle) * radius);
    shaft.rotation.y = rng() * TAU;
    shaft.renderOrder = 2;
    group.add(shaft);
    shafts.push(shaft);
  }
  return { group, shafts };
}

function createSnow(timeUniform) {
  const count = 1900;
  const positions = new Float32Array(count * 3);
  const sizes = new Float32Array(count);
  const phases = new Float32Array(count);
  const rng = mulberry32(72);
  for (let i = 0; i < count; i += 1) {
    positions[i * 3] = range(rng, -130, 130);
    positions[i * 3 + 1] = range(rng, -70, 70);
    positions[i * 3 + 2] = range(rng, -130, 130);
    sizes[i] = range(rng, 0.45, 2.3);
    phases[i] = rng() * TAU;
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));
  geometry.setAttribute('aPhase', new THREE.BufferAttribute(phases, 1));

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uTime: timeUniform,
      uPlayer: { value: new THREE.Vector3() },
    },
    vertexShader: `
      uniform float uTime;
      uniform vec3 uPlayer;
      attribute float aSize;
      attribute float aPhase;
      varying float vAlpha;
      void main() {
        vec3 p = position;
        p.x = mod(p.x - uPlayer.x + 130.0, 260.0) - 130.0 + uPlayer.x;
        p.y = mod(p.y - uPlayer.y + 70.0, 140.0) - 70.0 + uPlayer.y;
        p.z = mod(p.z - uPlayer.z + 130.0, 260.0) - 130.0 + uPlayer.z;
        p.y += sin(uTime * 0.22 + aPhase) * 0.7;
        p.x += cos(uTime * 0.15 + aPhase * 1.3) * 0.4;
        vec4 mv = modelViewMatrix * vec4(p, 1.0);
        gl_PointSize = aSize * (115.0 / max(1.0, -mv.z));
        gl_Position = projectionMatrix * mv;
        vAlpha = smoothstep(190.0, 18.0, -mv.z) * (0.35 + 0.65 * (0.5 + 0.5 * sin(uTime * 0.8 + aPhase)));
      }
    `,
    fragmentShader: `
      varying float vAlpha;
      void main() {
        float d = length(gl_PointCoord - vec2(0.5));
        float alpha = smoothstep(0.5, 0.05, d) * vAlpha * 0.56;
        gl_FragColor = vec4(vec3(0.66, 1.0, 0.9), alpha);
      }
    `,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    toneMapped: false,
  });
  const points = new THREE.Points(geometry, material);
  points.frustumCulled = false;
  return points;
}

class Bubbles {
  constructor(glowTexture) {
    this.count = 100;
    this.positions = new Float32Array(this.count * 3);
    this.velocities = Array.from({ length: this.count }, () => new THREE.Vector3());
    this.life = new Float32Array(this.count);
    this.geometry = new THREE.BufferGeometry();
    this.geometry.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    this.material = new THREE.PointsMaterial({
      map: glowTexture,
      color: 0xb9fff4,
      size: 0.17,
      sizeAttenuation: true,
      transparent: true,
      opacity: 0.48,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    this.points = new THREE.Points(this.geometry, this.material);
    this.points.frustumCulled = false;
    this.rng = mulberry32(101);
    this.next = 0;
    this.spawnTimer = 0;
  }

  spawn(player) {
    const i = this.next;
    this.next = (this.next + 1) % this.count;
    this.positions[i * 3] = player.x + range(this.rng, -0.7, 0.7);
    this.positions[i * 3 + 1] = player.y - 0.35 + range(this.rng, -0.3, 0.3);
    this.positions[i * 3 + 2] = player.z + range(this.rng, -0.7, 0.7);
    this.velocities[i].set(range(this.rng, -0.22, 0.22), range(this.rng, 0.35, 1.2), range(this.rng, -0.22, 0.22));
    this.life[i] = range(this.rng, 1.4, 3.2);
  }

  update(dt, player, moving) {
    this.spawnTimer -= dt;
    if (moving && this.spawnTimer <= 0) {
      this.spawn(player);
      this.spawnTimer = 0.055;
    }
    for (let i = 0; i < this.count; i += 1) {
      if (this.life[i] > 0) {
        this.life[i] -= dt;
        this.positions[i * 3] += this.velocities[i].x * dt;
        this.positions[i * 3 + 1] += this.velocities[i].y * dt;
        this.positions[i * 3 + 2] += this.velocities[i].z * dt;
        this.velocities[i].y += dt * 0.06;
      } else {
        this.positions[i * 3 + 1] = -1000;
      }
    }
    this.geometry.attributes.position.needsUpdate = true;
  }
}

class Motes {
  constructor(scene, glowTexture) {
    this.scene = scene;
    this.items = [];
    const positions = [
      [4, -9.5, 30], [-10, -15.5, 23], [1, -22, 8], [-16, -27, 15],
      [22, -20, 2], [14, -35, -18], [-35, -44, -10], [30, -47, -38],
      [-3, -60, -40], [44, -40, -62], [-24, -58, -48], [9, -74, -36],
      [52, -58, -24], [-48, -70, 14], [20, -84, -70], [-10, -92, -90],
    ];
    const coreGeo = new THREE.OctahedronGeometry(0.23, 0);
    const coreMat = new THREE.MeshBasicMaterial({ color: 0xc9fff3, transparent: true, opacity: 0.92, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
    for (const [x, y, z] of positions) {
      const group = new THREE.Group();
      group.position.set(x, y, z);
      const core = new THREE.Mesh(coreGeo, coreMat);
      group.add(core);
      const glow = createGlowSprite(glowTexture, 0x8dffe2, 2.2, 0.72);
      group.add(glow);
      group.userData = { base: new THREE.Vector3(x, y, z), phase: x * 0.4 + z * 0.2, collected: false, core, glow };
      scene.add(group);
      this.items.push(group);
    }
  }

  update(dt, time, player, onCollect) {
    for (const mote of this.items) {
      if (mote.userData.collected) continue;
      const { base, phase } = mote.userData;
      mote.position.set(
        base.x + Math.sin(time * 0.34 + phase) * 0.6,
        base.y + Math.sin(time * 0.72 + phase) * 0.45,
        base.z + Math.cos(time * 0.27 + phase) * 0.6
      );
      mote.rotation.y += dt * 0.7;
      mote.rotation.x += dt * 0.22;
      const scale = 1 + Math.sin(time * 1.6 + phase) * 0.12;
      mote.scale.setScalar(scale);
      if (mote.position.distanceTo(player) < 3.4) {
        mote.userData.collected = true;
        mote.visible = false;
        onCollect?.(mote);
      }
    }
  }
}

export class World {
  constructor(canvas) {
    this.canvas = canvas;
    this.time = 0;
    this.timeUniform = { value: 0 };
    this.glowTexture = makeGlowTexture(128);
    this.scene = new THREE.Scene();
    this.scene.fog = new THREE.FogExp2(0x052e37, 0.011);
    this.camera = new THREE.PerspectiveCamera(58, 1, 0.12, 460);
    this.camera.rotation.order = 'YXZ';
    this.camera.position.set(0, -13.5, 43);

    this.renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      alpha: false,
      powerPreference: 'high-performance',
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.06;
    this.renderer.setClearColor(0x03151b, 1);
    this.renderer.autoClear = true;

    this.hemi = new THREE.HemisphereLight(0x9bfff0, 0x021014, 1.7);
    this.scene.add(this.hemi);
    this.sun = new THREE.DirectionalLight(0xd5fff5, 2.9);
    this.sun.position.set(-30, 110, 40);
    this.scene.add(this.sun);
    this.fill = new THREE.DirectionalLight(0x3be9d0, 0.65);
    this.fill.position.set(30, -10, -60);
    this.scene.add(this.fill);
    this.scene.add(new THREE.AmbientLight(0x0c3b42, 0.45));

    this.sky = createSkyDome(this.timeUniform);
    this.scene.add(this.sky);

    this.surface = createOceanSurface(this.timeUniform);
    this.scene.add(this.surface);

    this.terrain = createTerrain(this.timeUniform);
    this.scene.add(this.terrain);

    this.rocks = createRocks();
    this.scene.add(this.rocks);

    this.kelp = createKelp(this.timeUniform);
    this.scene.add(this.kelp);

    this.spire = createSpire(this.timeUniform, this.glowTexture);
    this.scene.add(this.spire);

    const shafts = createShafts(this.timeUniform);
    this.shafts = shafts.shafts;
    this.scene.add(shafts.group);

    this.snow = createSnow(this.timeUniform);
    this.scene.add(this.snow);

    this.bubbles = new Bubbles(this.glowTexture);
    this.scene.add(this.bubbles.points);

    this.motes = new Motes(this.scene, this.glowTexture);

    this.pulseRing = new THREE.Mesh(
      new THREE.RingGeometry(0.985, 1.0, 96),
      new THREE.MeshBasicMaterial({ color: 0x8dffe5, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false })
    );
    this.pulseRing.visible = false;
    this.scene.add(this.pulseRing);
    this.pulseAge = 0;
    this.pulseActive = false;

    this.pulseRingFlat = new THREE.Mesh(
      new THREE.RingGeometry(0.975, 1.0, 96),
      new THREE.MeshBasicMaterial({ color: 0x6bffe0, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false })
    );
    this.pulseRingFlat.rotation.x = -Math.PI / 2;
    this.pulseRingFlat.visible = false;
    this.scene.add(this.pulseRingFlat);

    this.scanRing = new THREE.Mesh(
      new THREE.RingGeometry(0.86, 0.92, 48),
      new THREE.MeshBasicMaterial({ color: 0x8dffe5, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false })
    );
    this.scanRing.visible = false;
    this.scene.add(this.scanRing);

    this.scanLine = new THREE.Line(
      new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]),
      new THREE.LineBasicMaterial({ color: 0x8dffe5, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
    );
    this.scanLine.visible = false;
    this.scene.add(this.scanLine);

    this.depthFactor = 0;
    this.resize();
    window.addEventListener('resize', () => this.resize());
  }

  resize() {
    const width = window.innerWidth;
    const height = window.innerHeight;
    this.camera.aspect = width / height;
    this.camera.updateProjectionMatrix();
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
    this.renderer.setSize(width, height, false);
  }

  setScanTarget(target, active) {
    if (!target) {
      this.scanRing.visible = false;
      this.scanLine.visible = false;
      return;
    }
    this.scanRing.visible = true;
    this.scanLine.visible = true;
    const radius = target.species.range > 30 ? 3.4 : target.species.range > 18 ? 1.5 : 0.75;
    this.scanRing.position.copy(target.position);
    this.scanRing.quaternion.copy(this.camera.quaternion);
    const pulse = 1 + Math.sin(this.time * 3.2) * 0.12;
    this.scanRing.scale.setScalar(radius * pulse);
    this.scanRing.material.opacity = active ? 0.75 : 0.2;

    const positions = this.scanLine.geometry.attributes.position;
    positions.setXYZ(0, this.camera.position.x, this.camera.position.y - 0.6, this.camera.position.z);
    positions.setXYZ(1, target.position.x, target.position.y, target.position.z);
    positions.needsUpdate = true;
    this.scanLine.material.opacity = active ? 0.32 : 0.08;
  }

  firePulse(position) {
    this.pulseActive = true;
    this.pulseAge = 0;
    this.pulseRing.visible = true;
    this.pulseRingFlat.visible = true;
    this.pulseRing.position.copy(position);
    this.pulseRingFlat.position.copy(position);
    this.pulseRingFlat.position.y = Math.max(position.y - 0.5, -115);
  }

  collectMote() {
    // The visual pop is handled by the mote itself. Kept as a hook for effects.
  }

  update(dt, time, player, playerVelocity, scanTarget, scanActive) {
    this.time = time;
    this.timeUniform.value = time;
    this.depthFactor = clamp((-player.y - 5) / 100, 0, 1);

    const fog = this.scene.fog;
    if (this.depthFactor < 0.42) {
      fog.color.lerpColors(SHALLOW_FOG, MID_FOG, this.depthFactor / 0.42);
    } else {
      fog.color.lerpColors(MID_FOG, DEEP_FOG, (this.depthFactor - 0.42) / 0.58);
    }
    fog.density = lerp(0.0095, 0.0155, this.depthFactor);
    this.terrain.material.uniforms.uFogColor.value.copy(fog.color);
    this.terrain.material.uniforms.uFogDensity.value = fog.density;
    this.renderer.toneMappingExposure = lerp(1.08, 0.76, this.depthFactor);
    this.hemi.intensity = lerp(1.7, 0.52, this.depthFactor);
    this.sun.intensity = lerp(2.9, 0.45, this.depthFactor);
    this.fill.intensity = lerp(0.65, 0.3, this.depthFactor);
    this.sky.material.uniforms.uTop.value.lerpColors(new THREE.Color(0x03161e), new THREE.Color(0x01070b), this.depthFactor);
    this.sky.material.uniforms.uBottom.value.lerpColors(new THREE.Color(0x07353e), new THREE.Color(0x021017), this.depthFactor);

    this.snow.material.uniforms.uPlayer.value.copy(player);
    this.bubbles.update(dt, player, playerVelocity.lengthSq() > 0.6);
    this.motes.update(dt, time, player, () => this.collectMote());

    for (const shaft of this.shafts) {
      shaft.rotation.y = Math.atan2(this.camera.position.x - shaft.position.x, this.camera.position.z - shaft.position.z) + Math.sin(time * 0.03 + shaft.position.x) * 0.05;
    }

    const top = this.spire.userData.topCore;
    top.rotation.y += dt * 0.2;
    top.rotation.x += dt * 0.07;
    this.spire.userData.topGlow.material.opacity = 0.38 + Math.sin(time * 0.7) * 0.1;

    if (this.pulseActive) {
      this.pulseAge += dt;
      const t = this.pulseAge / 1.55;
      const scale = 1.5 + t * 64;
      this.pulseRing.scale.setScalar(scale);
      this.pulseRingFlat.scale.setScalar(scale * 0.82);
      this.pulseRing.material.opacity = Math.max(0, (1 - t) * 0.7);
      this.pulseRingFlat.material.opacity = Math.max(0, (1 - t) * 0.5);
      this.pulseRing.quaternion.copy(this.camera.quaternion);
      if (t >= 1) {
        this.pulseActive = false;
        this.pulseRing.visible = false;
        this.pulseRingFlat.visible = false;
      }
    }

    this.setScanTarget(scanTarget, scanActive);
  }

  render() {
    this.renderer.render(this.scene, this.camera);
  }
}

