391: function updatePlayer(dt, time) {
392:   if (!game.started) {
393:     const drift = Math.sin(time * 0.18) * 0.006;
394:     world.camera.position.set(
395:       player.position.x + Math.sin(time * 0.2) * 0.55,
396:       player.position.y + Math.sin(time * 0.34) * 0.18,
397:       player.position.z
398:     );
399:     world.camera.rotation.set(player.pitch + Math.sin(time * 0.23) * 0.006, player.yaw + drift, Math.sin(time * 0.17) * 0.003);
400:     return;
401:   }
402: 
403:   if (game.over) {
404:     world.camera.rotation.set(player.pitch, player.yaw, 0);
405:     return;
406:   }
407: 
408:   const look = input.consumeLook();
409:   player.yaw += look.yaw;
410:   player.pitch = clamp(player.pitch + look.pitch, -1.32, 1.24);
411: 
412:   const stickForward = input.touchStick.active ? input.touchStick.y : 0;
413:   const stickRight = input.touchStick.active ? input.touchStick.x : 0;
414:   const forwardInput = clamp(input.forward + stickForward, -1, 1);
415:   const rightInput = clamp(input.right + stickRight, -1, 1);
416:   const verticalInput = input.vertical;
417:   const boost = input.sprinting ? 1.9 : 1;
418:   const speed = 7.2 * boost;
419: 
420:   lookVector.set(
421:     -Math.sin(player.yaw) * Math.cos(player.pitch),
422:     Math.sin(player.pitch),
423:     -Math.cos(player.yaw) * Math.cos(player.pitch)
424:   ).normalize();
425:   rightVector.set(Math.cos(player.yaw), 0, -Math.sin(player.yaw)).normalize();
426: 
427:   moveVector.set(0, 0, 0);
428:   moveVector.addScaledVector(lookVector, forwardInput);
429:   moveVector.addScaledVector(rightVector, rightInput);
430:   moveVector.addScaledVector(upVector, verticalInput * 0.78);
431:   if (moveVector.lengthSq() > 1) moveVector.normalize();
432:   moveVector.multiplyScalar(speed);
433: 
434:   player.velocity.x = damp(player.velocity.x, moveVector.x, 3.2, dt);
435:   player.velocity.y = damp(player.velocity.y, moveVector.y, 3.2, dt);
436:   player.velocity.z = damp(player.velocity.z, moveVector.z, 3.2, dt);
437: 
438:   const current = new THREE.Vector3(
439:     Math.sin(time * 0.13 + player.position.z * 0.02) * 0.42,
440:     Math.sin(time * 0.09) * 0.12,
441:     Math.cos(time * 0.11 + player.position.x * 0.02) * 0.42
442:   );
443:   player.position.addScaledVector(player.velocity, dt);
444:   player.position.addScaledVector(current, dt);
445: 
446:   const radius = Math.hypot(player.position.x, player.position.z);
447:   if (radius > 232) {
448:     const scale = 232 / radius;
449:     player.position.x *= scale;
450:     player.position.z *= scale;
451:   }
452:   const floor = terrainHeight(player.position.x, player.position.z) + 2.8;
453:   player.position.y = clamp(player.position.y, Math.max(-112, floor), -1.1);
454: 
455:   const bobAmount = clamp(player.velocity.length() / 7.2, 0, 1);
456:   const bob = Math.sin(time * 2.1) * 0.075 * bobAmount;
457:   const sway = Math.sin(time * 1.3) * 0.035 * bobAmount;
458:   const shake = game.shake;
459:   if (shake > 0) game.shake = Math.max(0, shake - dt * 1.8);
460:   const shakeX = (Math.random() - 0.5) * shake * 0.38;
461:   const shakeY = (Math.random() - 0.5) * shake * 0.3;
462:   const shakeZ = (Math.random() - 0.5) * shake * 0.18;
463: 
464:   world.camera.position.set(
465:     player.position.x + sway + shakeX,
466:     player.position.y + bob + shakeY,
467:     player.position.z + shakeZ
468:   );
469:   world.camera.rotation.set(
470:     player.pitch + Math.sin(time * 1.7) * 0.0025,
471:     player.yaw,
472:     -rightInput * 0.018 + Math.sin(time * 1.1) * 0.003 + Math.sin(time * 62) * shake * 0.035
473:   );
474: 
475:   if (input.consumePulse()) firePulse();
476: }
