211: function createLoftGeometry({ length = 16, segments = 36, radial = 18, profile, seed = 1, ridge = 0.055 }) {
212:   const positions = [];
213:   const uvs = [];
214:   const colors = [];
215:   const indices = [];
216:   const rng = mulberry32(seed);
217:   const twist = range(rng, -0.1, 0.1);
