219:   for (let i = 0; i <= segments; i += 1) {
220:     const t = i / segments;
221:     const z = -length / 2 + t * length;
222:     const [rx, ry] = profile(t);
223:     for (let j = 0; j <= radial; j += 1) {
224:       const angle = (j / radial) * TAU;
225:       const ripple = 1 + Math.sin(angle * 7 + t * 12 + seed) * ridge + Math.sin(angle * 3 - t * 8) * ridge * 0.48;
226:       const x = Math.cos(angle) * rx * ripple;
227:       const y = Math.sin(angle) * ry * ripple;
228:       positions.push(x, y, z);
229:       uvs.push(j / radial, t);
230:       const topness = clamp(y / Math.max(ry, 0.001), -1, 1);
231:       const shade = 0.4 + topness * 0.19 + Math.sin(t * 19 + seed) * 0.035 + twist;
232:       colors.push(shade * 0.57, shade * 0.93, shade * 0.88);
233:     }
234:   }
235: 
236:   for (let i = 0; i < segments; i += 1) {
237:     for (let j = 0; j < radial; j += 1) {
238:       const a = i * (radial + 1) + j;
239:       const b = a + radial + 1;
240:       const c = b + 1;
241:       const d = a + 1;
242:       indices.push(a, b, d, b, c, d);
243:     }
244:   }
