815:     this.fleeTime -= dt;
816:     const toPlayer = new THREE.Vector3().subVectors(player, this.position);
817:     const distance = toPlayer.length();
818: 
819:     if (this.fleeTime > 0) {
820:       this.state = 'flee';
821:     } else if (this.state === 'flee' && this.fleeTime <= 0) {
822:       this.state = 'patrol';
823:       this.stateTime = 0;
824:       this.chargeCooldown = 6;
825:     } else if (this.state === 'patrol' && distance < 54 && this.chargeCooldown <= 0) {
826:       this.state = 'stalk';
