840:         this.state = 'retreat';
841:         this.stateTime = 0;
842:         this.chargeCooldown = 9;
843:       }
844:       if (distance < 4.4 && this.stateTime < 2.8) {
845:         this.onAttack?.(this);
846:         this.state = 'retreat';
847:         this.stateTime = 0;
848:         this.chargeCooldown = 10;
849:       }
850:     } else if (this.state === 'retreat' && this.stateTime > 3.5) {
851:       this.state = 'patrol';
852:       this.stateTime = 0;
853:       this.chargeCooldown = 6.5;
854:     }
