856:     let desired = new THREE.Vector3();
857:     let speed = this.patrolSpeed;
858:     if (this.state === 'patrol') {
859:       this.angle += dt * (this.patrolSpeed / this.radius);
860:       desired.set(
861:         this.center.x + Math.cos(this.angle) * this.radius,
862:         this.center.y + Math.sin(time * 0.23) * 5,
863:         this.center.z + Math.sin(this.angle) * this.radius
864:       );
865:       desired.sub(this.position);
866:       speed = 3.3;
867:     } else if (this.state === 'stalk') {
868:       const tangent = new THREE.Vector3(-toPlayer.z, 0, toPlayer.x).normalize();
869:       const orbit = player.clone().add(tangent.multiplyScalar(24)).add(new THREE.Vector3(0, 4, 0));
